﻿import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
  Logger,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AdminUsersService } from './admin-users.service';

/**
 * Dev-only admin access:
 * - In non-production, accepts x-dev-user-id and validates membership in admin_users table.
 * - In production, blocks all access until real authentication is wired (req.user).
 *
 * This replaces the old ADMIN_BYPASS behavior without reintroducing a global bypass.
 */
@Injectable()
export class AdminBypassGuard implements CanActivate {
  private readonly logger = new Logger(AdminBypassGuard.name);

  constructor(
    private readonly config: ConfigService,
    private readonly adminUsersService: AdminUsersService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    try {
      const req = context.switchToHttp().getRequest<any>();

      const nodeEnv =
        this.config.get<string>('NODE_ENV') ??
        process.env.NODE_ENV ??
        'development';

      const isProd = nodeEnv === 'production';

      // Future auth integration path
      const authedUserId =
        req?.user?.id != null ? String(req.user.id).trim() : '';

      // Dev-only header (ignored in production)
      const rawDevHeader = req?.headers?.['x-dev-user-id'];
      const devUserId =
        !isProd && typeof rawDevHeader === 'string'
          ? rawDevHeader.trim()
          : !isProd && Array.isArray(rawDevHeader) && rawDevHeader[0]
            ? String(rawDevHeader[0]).trim()
            : '';

      // In prod: only accept authenticated user id
      // In dev: accept header first, then fallback to authenticated user id if present
      const candidateId = isProd ? authedUserId : devUserId || authedUserId;

      if (!candidateId) {
        if (isProd) {
          throw new ForbiddenException(
            'Admin access is restricted until authentication is configured.',
          );
        }
        throw new ForbiddenException('Admin access required');
      }

      const isAdmin = await this.adminUsersService.isAdmin(candidateId);

      if (!isAdmin) {
        throw new ForbiddenException('Admin access required');
      }

      return true;
    } catch (err: any) {
      const msg = err?.message ?? String(err);
      this.logger.warn(`AdminBypassGuard denied: ${msg}`);

      if (err instanceof ForbiddenException) {
        throw err;
      }

      // Never crash the request path
      throw new ForbiddenException('Admin access required');
    }
  }
}

﻿import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

import { AdminUser } from './admin-user.entity';
import { User } from '../users/user.entity';
import { AccountType } from '../users/account-type.enum';

@Injectable()
export class AdminUsersService {
  private readonly logger = new Logger(AdminUsersService.name);

  constructor(
    @InjectRepository(AdminUser)
    private readonly adminRepo: Repository<AdminUser>,

    @InjectRepository(User)
    private readonly userRepo: Repository<User>,
  ) {}

  /**
   * Used by AdminBypassGuard
   */
  async isAdmin(userId: string): Promise<boolean> {
    try {
      const count = await this.adminRepo.count({
        where: { userId },
      });
      return count > 0;
    } catch (err) {
      this.logger.warn(
        `isAdmin failed for userId=${userId}. Defaulting to false.`,
      );
      return false;
    }
  }

  /**
   * GET /admin/users
   */
  async listUsers() {
    try {
      return await this.userRepo.find({
        select: ['id', 'email', 'accountType', 'createdAt', 'updatedAt'],
        order: {
          createdAt: 'DESC',
        },
      });
    } catch (err) {
      this.logger.error('listUsers failed', err);
      throw err;
    }
  }

  /**
   * PATCH /admin/users/:id
   */
  async updateUserAccountType(userId: string, accountType: AccountType) {
    const user = await this.userRepo.findOne({
      where: { id: userId },
    });

    if (!user) {
      throw new Error(`User not found: ${userId}`);
    }

    user.accountType = accountType;
    await this.userRepo.save(user);

    return {
      id: user.id,
      accountType: user.accountType,
    };
  }
}

import { BadRequestException } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { Baseline } from '../baseline/baseline.entity';
import { BaselineBlockPolicy } from '../baseline/baseline-block-policy.entity';
import {
  BaselineIncludePolicy,
  BaselineSection,
} from '../baseline/baseline-section.entity';
import { BaselineVersion } from '../baseline/baseline-version.entity';
import { ComplianceAction } from '../compliance/compliance.types';
import { ComplianceService } from '../compliance/compliance.service';
import { Job, JobIngestionMethod } from '../jobs/job.entity';
import { User } from '../users/user.entity';
import { Interview } from '../interviews/interview.entity';
import { ExpandedFitAssessment } from './expanded-fit-assessment.entity';
import { AnalysisService } from './analysis.service';
import { FitAssessment, FitAssessmentVerdict } from './fit-assessment.entity';
import { FitScoringService } from './fit-scoring.service';
import type { CalibrationProfile } from './calibration-profiles';

describe('AnalysisService - fit scores contract', () => {
  let service: AnalysisService;
  let complianceService: ComplianceService;
  let baselineVersionRepository: { findOne: jest.Mock };
  let fitAssessmentRepository: {
    create: jest.Mock;
    save: jest.Mock;
    findOne: jest.Mock;
  };
  let jobRepository: { findOne: jest.Mock };
  let fitScoringServiceMock: { score: jest.Mock };

  const baselineVersion: Partial<BaselineVersion> = {
    id: 'bv-1',
    baselineId: 'b-1',
    versionNumber: 2,
    baseline: { id: 'b-1', userId: 'user-1' } as Baseline,
  };

  const baselineSections: BaselineSection[] = [
    {
      id: 's-1',
      baselineId: 'b-1',
      sectionType: 'EXPERIENCE' as any,
      title: null,
      content: 'Implemented distributed systems and led platform teams.',
      includePolicy: BaselineIncludePolicy.OPTIONAL,
      order: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
    } as BaselineSection,
    {
      id: 's-2',
      baselineId: 'b-1',
      sectionType: 'SKILLS' as any,
      title: null,
      content: 'AWS, Kubernetes, Terraform',
      includePolicy: BaselineIncludePolicy.OPTIONAL,
      order: 1,
      createdAt: new Date(),
      updatedAt: new Date(),
    } as BaselineSection,
  ];

  const baseline: Baseline = {
    id: 'b-1',
    userId: 'user-1',
    version: 2,
    originalFilename: 'resume.pdf',
    mimeType: 'application/pdf',
    storagePath: '/tmp/resume.pdf',
    hash: 'hash',
    sections: baselineSections,
    versions: [],
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  const defaultJobRecord: Partial<Job> = {
    id: 'job-1',
    userId: 'user-1',
    rawDescription: 'Lead operations with AWS focus.',
    normalizedResponsibilities: ['Lead operations'],
    normalizedRequirements: ['AWS expertise'],
    jdIngestionMethod: JobIngestionMethod.PASTE,
    title: 'Cloud Lead',
    company: 'ExampleCo',
    sourceUrl: null,
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  beforeEach(async () => {
    baselineVersionRepository = {
      findOne: jest.fn().mockResolvedValue(baselineVersion),
    };
    jobRepository = { findOne: jest.fn().mockResolvedValue(defaultJobRecord) };
    fitScoringServiceMock = {
      score: jest.fn().mockResolvedValue({
        overallScore: 82,
        rawScore: 82,
        verdict: 'Apply',
        persistenceVerdict: FitAssessmentVerdict.APPLY,
        dimensionScores: {
          experienceAlignment: 80,
          leadershipLevel: 85,
          technicalPlatformFit: 70,
          industryContext: 75,
          strategicTacticalFit: 65,
        },
        strengths: [],
        gaps: [],
        summary: 'summary',
        missingRequiredTools: [],
        missingRequiredToolsCount: 0,
        missingRequiredToolsPenalty: 0,
        leadershipOverrideApplied: false,
        complianceFlags: [],
      }),
    };

    const module = await Test.createTestingModule({
      providers: [
        AnalysisService,
        {
          provide: FitScoringService,
          useValue: fitScoringServiceMock,
        },
        {
          provide: ComplianceService,
          useValue: {
            validateAndAudit: jest.fn().mockResolvedValue({
              complianceFlags: [],
              blocked: false,
              audit: {
                id: 'audit-1',
                outputHash: '',
                baselineVersionHash: 'hash',
                baselineVersionId: 'bv-1',
                action: ComplianceAction.FIT_SCORE,
                actorId: 'user-1',
                jobId: null,
                createdAt: new Date().toISOString(),
              },
            }),
            normalizeSectionsForOutput: jest
              .fn()
              .mockImplementation((sections) => sections),
            normalizeText: jest.fn().mockImplementation((text) => String(text)),
          },
        },
        {
          provide: getRepositoryToken(Baseline),
          useValue: { findOne: jest.fn().mockResolvedValue(baseline) },
        },
        {
          provide: getRepositoryToken(BaselineSection),
          useValue: { find: jest.fn().mockResolvedValue(baselineSections) },
        },
        {
          provide: getRepositoryToken(BaselineBlockPolicy),
          useValue: { find: jest.fn().mockResolvedValue([]) },
        },
        {
          provide: getRepositoryToken(BaselineVersion),
          useValue: baselineVersionRepository,
        },
        { provide: getRepositoryToken(Job), useValue: jobRepository },
        {
          provide: getRepositoryToken(Interview),
          useValue: { findOne: jest.fn() },
        },
        {
          provide: getRepositoryToken(FitAssessment),
          useValue: (() => {
            fitAssessmentRepository = {
              create: jest.fn((payload) => payload),
              save: jest.fn(async (payload) => ({
                ...payload,
                id: 'fit-1',
                createdAt: new Date(),
              })),
              findOne: jest.fn(),
            };

            return fitAssessmentRepository;
          })(),
        },
        {
          provide: getRepositoryToken(ExpandedFitAssessment),
          useValue: {
            create: jest.fn((payload) => payload),
            save: jest.fn(async (payload) => ({
              ...payload,
              id: 'exp-1',
              createdAt: new Date(),
            })),
          },
        },
        {
          provide: getRepositoryToken(User),
          useValue: {
            findOne: jest.fn().mockResolvedValue({
              id: 'user-1',
              calibrationProfileName: null,
              calibrationWeights: null,
            }),
          },
        },
      ],
    }).compile();

    service = module.get(AnalysisService);
    complianceService = module.get(ComplianceService);
  });

  it('returns the baseline version id for the latest assessment', async () => {
    fitAssessmentRepository.findOne.mockResolvedValue({
      id: 'fit-1',
      userId: 'user-1',
      jobId: 'job-1',
      baselineId: 'b-1',
      baselineVersion: 2,
      overallScore: 82,
      verdict: 'APPLY',
      dimensionScores: {
        experienceAlignment: 10,
        leadershipLevel: 9,
        technicalPlatformFit: 8,
        industryContext: 7,
        strategicTacticalFit: 6,
      },
      strengths: ['aws'],
      gaps: ['golang'],
      complianceFlags: [],
      createdAt: new Date(),
    });

    const result = await service.getLatestAssessment('user-1', 'job-1');

    expect(result.baselineVersionId).toBe('bv-1');
    expect(baselineVersionRepository.findOne).toHaveBeenCalledWith({
      where: { baselineId: 'b-1', versionNumber: 2 },
      order: { createdAt: 'DESC' },
    });
  });

  it('rejects ambiguous JD inputs', async () => {
    await expect(
      service.scoreCompatibility('user-1', {
        baseline_version_id: 'bv-1',
        job: { raw_jd_text: 'text', parsed_jd: { requirements: ['x'] } },
      }),
    ).rejects.toThrowError(
      expect.objectContaining({
        response: expect.objectContaining({
          error: expect.objectContaining({ code: 'JD_INPUT_AMBIGUOUS' }),
        }),
      }),
    );
  });

  it('rejects missing JD inputs', async () => {
    await expect(
      service.scoreCompatibility('user-1', {
        baseline_version_id: 'bv-1',
        job: {},
      }),
    ).rejects.toThrowError(
      expect.objectContaining({
        response: expect.objectContaining({
          error: expect.objectContaining({ code: 'JD_INPUT_MISSING' }),
        }),
      }),
    );
  });

  it('returns a contract-compliant success response', async () => {
    const result = await service.scoreCompatibility('user-1', {
      baseline_version_id: 'bv-1',
      job: {
        raw_jd_text: 'Lead cloud platforms with AWS and Kubernetes expertise.',
      },
    });

    expect(result).toEqual(
      expect.objectContaining({
        fit_score: expect.any(Number),
        overall_score: expect.any(Number),
        verdict: expect.any(String),
        breakdown: expect.objectContaining({
          experience_alignment: expect.any(Number),
          leadership_level: expect.any(Number),
          technical_platform_fit: expect.any(Number),
          industry_context: expect.any(Number),
          strategic_vs_tactical: expect.any(Number),
        }),
      }),
    );
    expect(result.strengths).toBeDefined();
    expect(result.scoring_v2).toEqual(
      expect.objectContaining({
        score: expect.any(Number),
        components: expect.objectContaining({
          scope: expect.any(Number),
          leadership: expect.any(Number),
        }),
        adjustments: expect.objectContaining({
          selfSimilarityApplied: expect.any(Boolean),
        }),
      }),
    );
    expect(result.audit_id).toBe('audit-1');
    expect(result.auditId).toBe('audit-1');
    expect(result.baseline_version_hash).toBe('hash');
  });

  it('creates a compliance audit for fit score requests', async () => {
    await service.scoreCompatibility('user-1', {
      baseline_version_id: 'bv-1',
      job: { raw_jd_text: 'Drive impact with measurable leadership results.' },
    });

    expect(complianceService.validateAndAudit).toHaveBeenCalledWith(
      expect.objectContaining({
        action: ComplianceAction.FIT_SCORE,
        actorId: 'user-1',
        outputHash: expect.any(String),
      }),
    );
  });

  it('returns scoring proof data when running a fit assessment', async () => {
    const jobRecord: Partial<Job> = {
      id: 'job-1',
      userId: 'user-1',
      rawDescription: 'Lead operations with AWS focus.',
      normalizedResponsibilities: ['Lead operations'],
      normalizedRequirements: ['AWS expertise'],
      jdIngestionMethod: JobIngestionMethod.PASTE,
      title: 'Cloud Lead',
      company: 'ExampleCo',
      sourceUrl: null,
    };
    jobRepository.findOne.mockResolvedValue(jobRecord);

    const result = await service.runFitAssessment('user-1', {
      baselineId: 'b-1',
      jobId: 'job-1',
      baselineVersion: 2,
    });

    expect(result.assessmentId).toBe('fit-1');
    expect(result.verdict).toBe('APPLY');
    expect(result.scoringProof?.assessmentId).toBe('fit-1');
    expect(result.scoringProof?.baselineTextCharsScored).toBeGreaterThan(0);
    expect(result.scoringProof?.jobTextCharsScored).toBeGreaterThan(0);
    expect(result.scoringProof).toMatchObject({
      normalizedResponsibilitiesCount: 1,
      normalizedRequirementsCount: 1,
      truncationAppliedBaseline: false,
      truncationAppliedJob: false,
    });
    const rawCharCount = jobRecord.rawDescription.trim().length;
    expect(result.scoringProof?.jobTextCharsScored).toBe(rawCharCount);
    expect(result.scoringProof?.jobTextSource).toBe('raw');
  });

  it('falls back to normalized segments when the raw description is missing', async () => {
    const fallbackJob: Partial<Job> = {
      id: 'job-2',
      userId: 'user-1',
      rawDescription: '',
      normalizedResponsibilities: ['Drive operational excellence'],
      normalizedRequirements: ['Leader level AWS experience'],
      jdIngestionMethod: JobIngestionMethod.PASTE,
      title: 'Operations Lead',
      company: 'ExampleCo',
      sourceUrl: null,
    };
    jobRepository.findOne.mockResolvedValueOnce(fallbackJob);

    const result = await service.runFitAssessment('user-1', {
      baselineId: 'b-1',
      jobId: 'job-2',
      baselineVersion: 2,
    });

    expect(result.scoringProof?.jobTextSource).toBe('normalized_fallback');
    expect(result.scoringProof?.jobRawTextCharCount).toBe(0);
    expect(result.scoringProof?.jobTextCharsScored).toBeGreaterThan(0);
  });

  describe('latest assessment refresh', () => {
    const refreshJobRecord: Job = {
      id: 'job-1',
      userId: 'user-1',
      rawDescription: '  Lead enterprise programs with narrative clarity.  ',
      normalizedResponsibilities: ['Lead teams'],
      normalizedRequirements: ['Executive-level experience'],
      title: 'Strategic Lead',
      company: 'ExampleCo',
      sourceUrl: 'https://example.com/jobs/leadership',
      jdIngestionMethod: JobIngestionMethod.PASTE,
      createdAt: new Date(),
      updatedAt: new Date(),
    } as Job;

    const dimensionWeights = {
      experienceAlignment: 1,
      leadershipLevel: 1,
      technicalPlatformFit: 1,
      industryContext: 1,
      strategicTacticalFit: 1,
    };

    let expectedHash: string;

    beforeEach(async () => {
      jobRepository.findOne.mockResolvedValue(refreshJobRecord);
      expectedHash = await service['computeExpectedInputsHashForJobBaseline'](
        'user-1',
        refreshJobRecord,
        baseline,
      );
    });

    it('buildInputsHash ignores normalized segments when raw description exists', () => {
      const filteredSections = service['getIncludedSections'](
        baseline.sections,
      );
      const sectionPayload = service['buildSectionPayload'](filteredSections);
      const { canonicalJobForHash: canonicalWith } = service[
        'buildCanonicalJobAssets'
      ]({
        rawDescription: refreshJobRecord.rawDescription,
        normalizedResponsibilities: refreshJobRecord.normalizedResponsibilities,
        normalizedRequirements: refreshJobRecord.normalizedRequirements,
        title: refreshJobRecord.title,
        company: refreshJobRecord.company,
        sourceUrl: refreshJobRecord.sourceUrl,
      });
      const { canonicalJobForHash: canonicalWithout } = service[
        'buildCanonicalJobAssets'
      ]({
        rawDescription: refreshJobRecord.rawDescription,
        normalizedResponsibilities: [],
        normalizedRequirements: [],
        title: refreshJobRecord.title,
        company: refreshJobRecord.company,
        sourceUrl: refreshJobRecord.sourceUrl,
      });

      const hashWithNormalized = service['buildInputsHash'](
        canonicalWith,
        baseline.id,
        baseline.version ?? null,
        sectionPayload,
        dimensionWeights,
      );
      const hashWithoutNormalized = service['buildInputsHash'](
        canonicalWithout,
        baseline.id,
        baseline.version ?? null,
        sectionPayload,
        dimensionWeights,
      );

      expect(hashWithoutNormalized).toBe(hashWithNormalized);
    });

    it('returns the stored assessment when inputs hash matches', async () => {
      const storedAssessment: FitAssessment = {
        id: 'fit-old',
        userId: 'user-1',
        jobId: 'job-1',
        baselineId: 'b-1',
        baselineVersion: baseline.version,
        overallScore: 72,
        verdict: FitAssessmentVerdict.APPLY,
        dimensionScores: {
          experienceAlignment: 70,
          leadershipLevel: 70,
          technicalPlatformFit: 70,
          industryContext: 70,
          strategicTacticalFit: 70,
        },
        strengths: ['leadership'],
        gaps: ['detail'],
        complianceFlags: [],
        inputsHash: expectedHash,
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      fitAssessmentRepository.findOne.mockResolvedValue(storedAssessment);

      const result = await service.getLatestAssessmentForBaseline(
        'user-1',
        'job-1',
        'b-1',
      );

      expect(result.assessmentId).toBe(storedAssessment.id);
      expect(result.overallScore).toBe(storedAssessment.overallScore);
      expect(fitScoringServiceMock.score).not.toHaveBeenCalled();
    });

    it('recomputes when the stored inputs hash is stale', async () => {
      const staleAssessment: FitAssessment = {
        id: 'fit-old',
        userId: 'user-1',
        jobId: 'job-1',
        baselineId: 'b-1',
        baselineVersion: baseline.version,
        overallScore: 41,
        verdict: FitAssessmentVerdict.CONSIDER,
        dimensionScores: {
          experienceAlignment: 40,
          leadershipLevel: 40,
          technicalPlatformFit: 40,
          industryContext: 40,
          strategicTacticalFit: 40,
        },
        strengths: [],
        gaps: [],
        complianceFlags: [],
        inputsHash: 'stale-hash',
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      let savedAssessment: FitAssessment | null = null;

      fitAssessmentRepository.save.mockImplementation(async (payload) => {
        savedAssessment = {
          ...payload,
          id: 'fresh-fit',
          createdAt: new Date(),
        } as FitAssessment;
        return savedAssessment;
      });

      fitAssessmentRepository.findOne.mockImplementation(({ where }) => {
        if (where?.id) {
          return Promise.resolve(savedAssessment);
        }
        return Promise.resolve(staleAssessment);
      });

      const result = await service.getLatestAssessmentForBaseline(
        'user-1',
        'job-1',
        'b-1',
      );

      expect(fitScoringServiceMock.score).toHaveBeenCalled();
      expect(savedAssessment).not.toBeNull();
      expect(savedAssessment?.inputsHash).toBe(expectedHash);
      expect(result.assessmentId).toBe(savedAssessment?.id);
    });
  });

  describe('calibrated scoring', () => {
    it('returns a calibration payload with delta metadata', async () => {
      const assessmentRecord: FitAssessment = {
        id: 'fit-1',
        userId: 'user-1',
        jobId: 'job-1',
        baselineId: 'b-1',
        baselineVersion: baseline.version,
        overallScore: 70,
        verdict: FitAssessmentVerdict.CONSIDER,
        dimensionScores: {
          experienceAlignment: 70,
          leadershipLevel: 70,
          technicalPlatformFit: 70,
          industryContext: 70,
          strategicTacticalFit: 70,
        },
        strengths: [],
        gaps: [],
        complianceFlags: [],
        inputsHash: 'hash-1',
        createdAt: new Date('2024-01-01T00:00:00.000Z'),
      };

      fitAssessmentRepository.findOne.mockResolvedValueOnce(assessmentRecord);

      const result = await service.calibrateAssessment(
        'user-1',
        'fit-1',
        'aggressive',
      );

      expect(result.ok).toBe(true);
      expect(result.assessmentId).toBe('fit-1');
      expect(result.overallScore).toBe(82);
      expect(result.baselineVersionId).toBe('bv-1');
      expect(result.summary).toBe('No keywords found in the job description.');
      expect(result.calibration).toMatchObject({
        profile: 'aggressive',
        label: 'Aggressive',
        delta: 12,
      });
    });

    it('rejects unsupported profiles', async () => {
      await expect(
        service.calibrateAssessment(
          'user-1',
          'fit-1',
          'unsupported' as CalibrationProfile,
        ),
      ).rejects.toThrow(BadRequestException);
    });
  });
});

import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { createHash } from 'crypto';
import { Repository } from 'typeorm';
import { Baseline } from '../baseline/baseline.entity';
import {
  BaselineIncludePolicy,
  BaselineSection,
  BaselineSectionType,
} from '../baseline/baseline-section.entity';
import { BaselineBlockPolicy } from '../baseline/baseline-block-policy.entity';
import { BaselineVersion } from '../baseline/baseline-version.entity';
import { ComplianceService } from '../compliance/compliance.service';
import {
  ComplianceAction,
  ComplianceFlag,
  ComplianceFlagSeverity,
} from '../compliance/compliance.types';
import { Interview } from '../interviews/interview.entity';
import { RecommendedAddition } from '../interviews/interview-types';
import { Job, JobIngestionMethod } from '../jobs/job.entity';
import { CalibrationWeights, User } from '../users/user.entity';
import { ExpandedFitAssessment } from './expanded-fit-assessment.entity';
import {
  FitAssessment,
  FitAssessmentVerdict,
  FitDimensionScores,
} from './fit-assessment.entity';
import type { RunFitAssessmentDto } from './dto/run-fit-assessment.dto';
import type { RunExpandedFitAssessmentDto } from './dto/run-expanded-fit-assessment.dto';
import {
  DimensionWeightOverrides,
  FitScoringService,
} from './fit-scoring.service';
import { scoreCxFitV2 } from './cx-fit-scoring-v2';

import { countWords, getCharCount, sha256 } from '../common/text-metrics';
import { buildJobPromptText } from '../scoring/fit-score/fit-score.utils';
import type { FitScoreInput } from '../scoring/fit-score/fit-score.types';
import type { FitScoreVerdictLabel } from '../scoring/fit-score/fit-verdict';
import type { FitScoreRubricJson } from './prompts/fit-score-rubric.v1';

export type AnalysisRequest = {
  baselineId: string;
  jobId?: string;
  jobDescription?: string;
};

export type AnalysisResult = {
  ok: boolean;
  baselineId: string;
  score: number;
  strengths: string[];
  gaps: string[];
  summary: string;
  compliance_flags?: Array<{ code: string; message?: string }>;
  audit_id?: string | null;
  auditId?: string | null;
  baseline_version_hash?: string | null;
};

type FitScoreJobInput = {
  id?: string;
  raw_jd_text?: string;
  raw_jd?: string;
  parsed_jd?: {
    responsibilities?: string[];
    requirements?: string[];
  };
};

export type DebugSource = 'header' | 'query' | 'body' | 'none';

export type FitScoreRequest = {
  job?: FitScoreJobInput;
  baseline_version_id?: string;
  debug?: boolean;
  debugSource?: DebugSource;
  selected_block_ids?: string[];
};

export type JobTextSource = 'raw' | 'raw+normalized' | 'normalized_fallback';

export type JobTextInput = {
  rawDescription?: string | null;
  normalizedResponsibilities?: string[] | null;
  normalizedRequirements?: string[] | null;
};

export type JobTextForScoring = {
  jobText: string;
  jobTextSource: JobTextSource;
  jobRawTextCharCount: number;
  jobRawTextSha256: string;
  jobRawTextTooShort: boolean;
  jobRawTextWarning?: string;
};

const RAW_TEXT_WARNING_THRESHOLD = 3000;

export function buildJobTextForScoring(job: JobTextInput): JobTextForScoring {
  const rawDescription = (job.rawDescription ?? '').trim();
  const normalizedResponsibilities = (
    job.normalizedResponsibilities ?? []
  ).filter(Boolean);
  const normalizedRequirements = (job.normalizedRequirements ?? []).filter(
    Boolean,
  );
  const normalizedText = [
    ...normalizedResponsibilities,
    ...normalizedRequirements,
  ].join('\n');
  const jobPrompt = buildJobPromptText({
    rawDescription,
    normalizedResponsibilities,
    normalizedRequirements,
  });

  const hasRaw = rawDescription.length > 0;
  const hasNormalized = Boolean(
    normalizedResponsibilities.length || normalizedRequirements.length,
  );

  if (!hasRaw && !hasNormalized) {
    throw new BadRequestException(
      'Job description text is required for scoring.',
    );
  }

  const jobTextSource: JobTextSource = hasRaw ? 'raw' : 'normalized_fallback';
  const jobText = hasRaw ? rawDescription : jobPrompt.text || normalizedText;

  const jobRawTextCharCount = getCharCount(rawDescription);
  const jobRawTextSha256 = sha256(rawDescription);
  const jobRawTextTooShort =
    jobRawTextCharCount > 0 && jobRawTextCharCount < RAW_TEXT_WARNING_THRESHOLD;
  const jobRawTextWarning = jobRawTextTooShort
    ? `Raw job description is only ${jobRawTextCharCount.toLocaleString()} characters (<${RAW_TEXT_WARNING_THRESHOLD.toLocaleString()}); scoring may be less reliable.`
    : undefined;

  return {
    jobText,
    jobTextSource,
    jobRawTextCharCount,
    jobRawTextSha256,
    jobRawTextTooShort,
    jobRawTextWarning,
  };
}

type ScoringProofSnapshot = {
  assessmentId: string | null;
  baselineTextCharsScored: number;
  jobTextCharsScored: number;
  truncationAppliedBaseline: boolean;
  truncationAppliedJob: boolean;
  normalizedResponsibilitiesCount: number;
  normalizedRequirementsCount: number;
  jobRawTextCharCount: number;
  jobRawTextSha256: string;
  jobRawTextTooShort: boolean;
  jobRawTextWarning?: string | null;
  jobTextSource: JobTextSource;
};

type CompatibilityRunDebugPayload = {
  baselineId: string;
  baselineVersionHash: string | null;
  baselineSelectedSectionCount: number;
  baselineTotalChars: number;
  jobId: string | null;
  jobRawChars: number;
  normalizedResponsibilitiesCount: number;
  normalizedResponsibilitiesChars: number;
  normalizedRequirementsCount: number;
  normalizedRequirementsChars: number;
  dimensionScores: FitDimensionScores;
  totalScore: number;
  jobRawTextCharCount: number;
  jobRawTextSha256: string;
  jobRawTextTooShort: boolean;
  jobRawTextWarning?: string | null;
  jobTextSource: JobTextSource;
};

type FitScoreResponse = {
  fit_score: number;
  overall_score: number;
  verdict: FitScoreVerdictLabel | FitScoreRubricJson['verdict'];
  breakdown: {
    experience_alignment: number;
    leadership_level: number;
    technical_platform_fit: number;
    industry_context: number;
    strategic_vs_tactical: number;
  };
  strengths?: string[];
  gaps?: string[];
  compliance_flags?: Array<{ code: string; message?: string }>;
  audit_id?: string | null;
  auditId?: string | null;
  assessmentId?: string;
  jobId?: string;
  baselineId?: string;
  baselineVersion?: number | null;
  createdAt?: Date;
  score?: number;
  overallScore?: number;
  dimensionScores?: FitAssessment['dimensionScores'];
  complianceFlags?: FitAssessment['complianceFlags'];
  summary?: string;
  debug?: CompatibilityRunDebugPayload;
  scoringProof?: ScoringProofSnapshot;

  // Added to match runtime return payload.
  scoring_v2?: unknown;
};

@Injectable()
export class AnalysisService {
  constructor(
    @InjectRepository(Baseline)
    private readonly baselineRepository: Repository<Baseline>,
    @InjectRepository(BaselineSection)
    private readonly baselineSectionRepository: Repository<BaselineSection>,
    @InjectRepository(BaselineBlockPolicy)
    private readonly baselineBlockPolicyRepository: Repository<BaselineBlockPolicy>,
    @InjectRepository(BaselineVersion)
    private readonly baselineVersionRepository: Repository<BaselineVersion>,
    @InjectRepository(Job)
    private readonly jobRepository: Repository<Job>,
    @InjectRepository(Interview)
    private readonly interviewRepository: Repository<Interview>,
    @InjectRepository(FitAssessment)
    private readonly fitAssessmentRepository: Repository<FitAssessment>,
    @InjectRepository(ExpandedFitAssessment)
    private readonly expandedFitAssessmentRepository: Repository<ExpandedFitAssessment>,
    @InjectRepository(User)
    private readonly usersRepository: Repository<User>,
    private readonly fitScoringService: FitScoringService,
    private readonly complianceService: ComplianceService,
  ) {}

  // VERIFY: Confirm default calibration values with product stakeholders.
  private readonly defaultCalibration: {
    profileName: string;
    weights: CalibrationWeights;
  } = {
    profileName: 'default',
    weights: {
      dimensionA: 1,
      dimensionB: 1,
      dimensionC: 1,
      dimensionD: 1,
      dimensionE: 1,
    },
  };

  private normalizeKeywords(text: string) {
    const tokens =
      text
        .toLowerCase()
        .match(/[a-z0-9]+/g)
        ?.filter((token) => token.length >= 3) ?? [];

    const frequencies = new Map<string, number>();
    for (const token of tokens) {
      frequencies.set(token, (frequencies.get(token) ?? 0) + 1);
    }

    return frequencies;
  }

  private sortByFrequency(values: Map<string, number>, items: string[]) {
    return [...items].sort((a, b) => {
      const delta = (values.get(b) ?? 0) - (values.get(a) ?? 0);
      if (delta !== 0) return delta;
      return a.localeCompare(b);
    });
  }

  private buildBaselineText(sections: BaselineSection[]) {
    return sections
      .filter(
        (section) => section.includePolicy !== BaselineIncludePolicy.NEVER,
      )
      .map((section) => section.content)
      .join('\n');
  }

  private buildSummaryFromTerms(strengths: string[], gaps: string[]) {
    if (!strengths.length && !gaps.length) {
      return 'No keywords found in the job description.';
    }
    const total = strengths.length + gaps.length;
    return `Matched ${strengths.length} of ${total} key terms from the job description.`;
  }

  private buildCanonicalJobInputs(jobProps: {
    rawDescription?: string | null;
    normalizedResponsibilities?: string[] | null;
    normalizedRequirements?: string[] | null;
  }) {
    const rawDescription = (jobProps.rawDescription ?? '').trim();
    const normalizedResponsibilities =
      rawDescription.length > 0
        ? []
        : (jobProps.normalizedResponsibilities ?? []).filter(Boolean);
    const normalizedRequirements =
      rawDescription.length > 0
        ? []
        : (jobProps.normalizedRequirements ?? []).filter(Boolean);

    return {
      rawDescription,
      normalizedResponsibilities,
      normalizedRequirements,
    };
  }

  private buildCanonicalJobAssets(jobProps: {
    rawDescription?: string | null;
    normalizedResponsibilities?: string[] | null;
    normalizedRequirements?: string[] | null;
    title?: string | null;
    company?: string | null;
    sourceUrl?: string | null;
  }) {
    const canonicalInputs = this.buildCanonicalJobInputs(jobProps);
    const jobTextForScoring = buildJobTextForScoring({
      rawDescription: canonicalInputs.rawDescription,
      normalizedResponsibilities: canonicalInputs.normalizedResponsibilities,
      normalizedRequirements: canonicalInputs.normalizedRequirements,
    });

    const canonicalJobForHash: FitScoreInput['job'] = {
      rawDescription: canonicalInputs.rawDescription,
      normalizedResponsibilities: canonicalInputs.normalizedResponsibilities,
      normalizedRequirements: canonicalInputs.normalizedRequirements,
      title: jobProps.title ?? null,
      company: jobProps.company ?? null,
    };

    const canonicalJobForScoring: FitScoreInput['job'] = {
      ...canonicalJobForHash,
      sourceUrl: jobProps.sourceUrl ?? null,
      jobTextOverride: jobTextForScoring.jobText,
    };

    return {
      canonicalJobForScoring,
      canonicalJobForHash,
      jobTextForScoring,
    };
  }

  private getIncludedSections(
    sections: BaselineSection[] | undefined,
    selectedBlockIds?: string[] | null,
  ) {
    return (sections ?? []).filter((section) => {
      if (section.includePolicy === BaselineIncludePolicy.NEVER) {
        return false;
      }
      if (selectedBlockIds && !selectedBlockIds.includes(section.id)) {
        return false;
      }
      return true;
    });
  }

  private buildSectionPayload(sections: BaselineSection[]) {
    return sections.map((section) => ({
      type: section.sectionType ?? section.type,
      content: section.content ?? '',
    }));
  }

  private buildInputsHash(
    job: FitScoreInput['job'],
    baseline: Baseline,
    dimensionWeights: DimensionWeightOverrides,
  ) {
    const sectionPayload = this.buildSectionPayload(baseline.sections ?? []);
    const payload = {
      job: {
        rawDescription: job.rawDescription,
        normalizedResponsibilities: job.normalizedResponsibilities,
        normalizedRequirements: job.normalizedRequirements,
        title: job.title ?? null,
        company: job.company ?? null,
      },
      baseline: {
        id: baseline.id,
        version: baseline.version ?? null,
        sections: sectionPayload,
      },
      calibration: dimensionWeights,
    };

    return createHash('sha256').update(JSON.stringify(payload)).digest('hex');
  }

  private async loadBaselineWithSections(userId: string, baselineId: string) {
    const baseline = await this.baselineRepository.findOne({
      where: { id: baselineId, userId },
      relations: ['sections'],
      order: { sections: { order: 'ASC' } },
    });

    if (!baseline) {
      throw new NotFoundException('Baseline not found');
    }

    if (!baseline.sections?.length) {
      baseline.sections = await this.baselineSectionRepository.find({
        where: { baselineId: baseline.id },
        order: { order: 'ASC' },
      });
    }

    return baseline;
  }

  private async fetchJobForUser(jobId: string, userId: string) {
    const job = await this.jobRepository.findOne({
      where: { id: jobId, userId },
    });

    if (!job) {
      throw new NotFoundException('Job not found');
    }

    return job;
  }

  private async computeExpectedInputsHashForJobBaseline(
    userId: string,
    job: Job,
    baseline: Baseline,
  ) {
    const calibration = await this.getCalibration(userId);
    const dimensionWeights = this.mapCalibrationToDimensionWeights(
      calibration.weights,
    );
    const includedSections = this.getIncludedSections(baseline.sections);
    const { canonicalJobForHash } = this.buildCanonicalJobAssets({
      rawDescription: job.rawDescription,
      normalizedResponsibilities: job.normalizedResponsibilities ?? [],
      normalizedRequirements: job.normalizedRequirements ?? [],
      title: job.title ?? null,
      company: job.company ?? null,
      sourceUrl: job.sourceUrl ?? null,
    });
    const baselineForHash: Baseline = {
      ...baseline,
      sections: includedSections,
    };
    return this.buildInputsHash(
      canonicalJobForHash,
      baselineForHash,
      dimensionWeights,
    );
  }

  private async runAndPersistFitAssessment(
    userId: string,
    jobId: string,
    baselineId: string,
    baselineVersion?: number,
  ) {
    const payload: RunFitAssessmentDto = { jobId, baselineId };
    if (baselineVersion !== undefined) {
      payload.baselineVersion = baselineVersion;
    }

    const result = await this.runFitAssessment(userId, payload);
    return this.getFitAssessmentById(userId, result.assessmentId);
  }

  private buildCompatibilityDebugPayload({
    baselineId,
    baselineVersionHash,
    baselineSelectedSectionCount,
    baselineTotalChars,
    jobId,
    jobRawChars,
    normalizedResponsibilitiesCount,
    normalizedResponsibilitiesChars,
    normalizedRequirementsCount,
    normalizedRequirementsChars,
    dimensionScores,
    totalScore,
    jobRawTextCharCount,
    jobRawTextSha256,
    jobRawTextTooShort,
    jobRawTextWarning,
    jobTextSource,
  }: {
    baselineId: string;
    baselineVersionHash: string | null;
    baselineSelectedSectionCount: number;
    baselineTotalChars: number;
    jobId: string | null;
    jobRawChars: number;
    normalizedResponsibilitiesCount: number;
    normalizedResponsibilitiesChars: number;
    normalizedRequirementsCount: number;
    normalizedRequirementsChars: number;
    dimensionScores: FitDimensionScores;
    totalScore: number;
    jobRawTextCharCount: number;
    jobRawTextSha256: string;
    jobRawTextTooShort: boolean;
    jobRawTextWarning?: string | null;
    jobTextSource: JobTextSource;
  }): CompatibilityRunDebugPayload {
    return {
      baselineId,
      baselineVersionHash,
      baselineSelectedSectionCount,
      baselineTotalChars,
      jobId,
      jobRawChars,
      normalizedResponsibilitiesCount,
      normalizedResponsibilitiesChars,
      normalizedRequirementsCount,
      normalizedRequirementsChars,
      dimensionScores,
      totalScore,
      jobRawTextCharCount,
      jobRawTextSha256,
      jobRawTextTooShort,
      jobRawTextWarning,
      jobTextSource,
    };
  }

  private buildNormalizedSegmentStats(segments: string[]) {
    const text = segments.join('\n');
    return {
      count: segments.length,
      chars: getCharCount(text),
    };
  }

  private coerceComplianceFlags(flags?: ComplianceFlag[] | string[] | null) {
    if (!flags?.length) return undefined;
    return flags.map((flag) => {
      if (typeof flag === 'string') {
        return { code: flag, message: flag };
      }
      return { code: flag.code, message: flag.message };
    });
  }

  private mapComplianceStringsToFlags(
    flags?: string[] | null,
  ): ComplianceFlag[] | undefined {
    if (!flags?.length) return undefined;
    return flags.map((flag) => ({
      code: flag as any,
      message: flag,
      severity: ComplianceFlagSeverity.BLOCK,
    }));
  }

  private normalizeAdditions(
    additions?: (string | RecommendedAddition)[] | null,
  ) {
    if (!additions?.length) return [];
    return additions
      .map((entry) => (typeof entry === 'string' ? entry : entry?.text)?.trim())
      .filter((entry): entry is string => Boolean(entry));
  }

  private assertJobInput(job?: FitScoreJobInput) {
    const rawText = job?.raw_jd_text ?? job?.raw_jd;
    const hasRaw = Boolean(rawText?.trim());
    const parsed = job?.parsed_jd;
    const hasParsed = Boolean(
      parsed &&
      ((parsed.responsibilities && parsed.responsibilities.length > 0) ||
        (parsed.requirements && parsed.requirements.length > 0)),
    );
    const hasId = Boolean(job?.id?.trim());
    const providedCount = Number(hasRaw) + Number(hasParsed);

    if (hasId && providedCount > 0) {
      throw new BadRequestException({
        error: {
          code: 'JD_INPUT_AMBIGUOUS',
          message: 'Provide either job.id or JD content, not both.',
        },
      });
    }

    if (!hasId && providedCount === 0) {
      throw new BadRequestException({
        error: {
          code: 'JD_INPUT_MISSING',
          message:
            'Provide exactly one of raw_jd_text (or raw_jd) or parsed_jd.',
        },
      });
    }

    if (providedCount > 1) {
      throw new BadRequestException({
        error: {
          code: 'JD_INPUT_AMBIGUOUS',
          message:
            'Provide exactly one of raw_jd_text (or raw_jd) or parsed_jd.',
        },
      });
    }
  }

  async getCalibration(userId: string) {
    const user = await this.usersRepository.findOne({ where: { id: userId } });

    if (!user) {
      throw new NotFoundException('User not found');
    }

    const profileName =
      user.calibrationProfileName ?? this.defaultCalibration.profileName;
    const weights =
      user.calibrationWeights ??
      ({ ...this.defaultCalibration.weights } as CalibrationWeights);

    return { ok: true, profileName, weights };
  }

  async saveCalibration(
    userId: string,
    payload: { profileName?: string; weights?: CalibrationWeights | null },
  ) {
    const profileName = payload.profileName?.trim();

    if (!profileName) {
      throw new BadRequestException('profileName is required');
    }

    // VERIFY: Validate calibration weight ranges with data science.
    if (!payload.weights) {
      throw new BadRequestException('weights are required');
    }

    const user = await this.usersRepository.findOne({ where: { id: userId } });

    if (!user) {
      throw new NotFoundException('User not found');
    }

    user.calibrationProfileName = profileName;
    user.calibrationWeights = payload.weights;

    await this.usersRepository.save(user);

    return { ok: true, profileName, weights: payload.weights };
  }

  private buildJobPayloadFromParsed(job: FitScoreJobInput) {
    const parsed = job.parsed_jd ?? {};
    const responsibilities = parsed.responsibilities ?? [];
    const requirements = parsed.requirements ?? [];
    const synthesizedRaw = [...responsibilities, ...requirements]
      .join('\n')
      .trim();

    return {
      title: null,
      company: null,
      rawDescription: job.raw_jd_text ?? job.raw_jd ?? synthesizedRaw,
      normalizedResponsibilities: responsibilities,
      normalizedRequirements: requirements,
      sourceUrl: null,
    };
  }

  private mapCalibrationToDimensionWeights(
    weights?: CalibrationWeights | null,
  ) {
    return {
      experienceAlignment: weights?.dimensionA ?? 1,
      technicalPlatformFit: weights?.dimensionB ?? 1,
      leadershipLevel: weights?.dimensionC ?? 1,
      strategicTacticalFit: weights?.dimensionD ?? 1,
      industryContext: weights?.dimensionE ?? 1,
    } satisfies DimensionWeightOverrides;
  }

  private applyPoliciesToSections(
    sections: BaselineSection[],
    policies: BaselineBlockPolicy[],
  ) {
    if (!policies.length) {
      return [...sections].sort((a, b) => a.order - b.order);
    }

    const policyMap = new Map<string, BaselineBlockPolicy>(
      policies.map((policy) => [policy.baselineSectionId, policy]),
    );

    return [...sections]
      .map((section) => {
        const policy = policyMap.get(section.id);
        return {
          ...section,
          includePolicy: policy?.includePolicy ?? section.includePolicy,
          order: policy?.order ?? section.order,
          sectionType: section.sectionType ?? section.type,
        } as BaselineSection;
      })
      .sort((a, b) => a.order - b.order);
  }

  private async loadBaselineForVersion(
    userId: string,
    baselineVersionId?: string,
  ) {
    if (!baselineVersionId?.trim()) {
      throw new BadRequestException('baseline_version_id is required');
    }

    const baselineVersion = await this.baselineVersionRepository.findOne({
      where: { id: baselineVersionId },
      relations: ['baseline'],
    });

    if (!baselineVersion || !baselineVersion.baseline) {
      throw new NotFoundException('Baseline version not found');
    }

    if (baselineVersion.baseline.userId !== userId) {
      throw new NotFoundException('Baseline version not found');
    }

    const baseline = await this.baselineRepository.findOne({
      where: { id: baselineVersion.baselineId, userId },
      relations: ['sections'],
      order: { sections: { order: 'ASC' } },
    });

    if (!baseline) {
      throw new NotFoundException('Baseline not found');
    }

    const policies = await this.baselineBlockPolicyRepository.find({
      where: { baselineVersionId: baselineVersion.id },
      relations: ['baselineSection'],
      order: { order: 'ASC' },
    });

    baseline.sections = this.applyPoliciesToSections(
      baseline.sections ?? [],
      policies,
    );

    const additionSections =
      (baselineVersion.verifiedAdditions ?? []).map((content, index) => {
        const section: Partial<BaselineSection> = {
          id: `addition-${index}`,
          baselineId: baseline.id,
          sectionType: BaselineSectionType.OTHER,
          title: 'Verified addition',
          content,
          includePolicy: BaselineIncludePolicy.ALWAYS,
          order: (baseline.sections?.length ?? 0) + index,
        };
        return section as BaselineSection;
      }) ?? [];

    baseline.sections = [...(baseline.sections ?? []), ...additionSections];

    return { baseline, baselineVersion };
  }

  async scoreCompatibility(
    userId: string,
    payload: FitScoreRequest,
  ): Promise<FitScoreResponse> {
    this.assertJobInput(payload.job);

    const { baseline, baselineVersion } = await this.loadBaselineForVersion(
      userId,
      payload.baseline_version_id,
    );

    if (!baseline.sections?.length) {
      baseline.sections = await this.baselineSectionRepository.find({
        where: { baselineId: baseline.id },
        order: { order: 'ASC' },
      });
    }

    const selectedBlockIds = payload.selected_block_ids?.filter(Boolean);
    const filteredSections = this.getIncludedSections(
      baseline.sections,
      selectedBlockIds,
    );
    const includedSections = filteredSections.map((section) => ({
      type: section.sectionType ?? section.type,
      content: section.content,
    }));
    const sectionPayload = includedSections;

    const complianceBaselineSections =
      this.complianceService.normalizeSectionsForOutput(includedSections);

    const baselineProofText = includedSections
      .map((section) => section.content ?? '')
      .join('\n');
    const baselineTextCharsScored = getCharCount(baselineProofText);

    const baselineTextForDebug = includedSections
      .map((section) => section.content)
      .join('\n');
    const baselineExtractedTextChars = getCharCount(baselineTextForDebug);
    const baselineExtractedTextWords = countWords(baselineTextForDebug);
    const baselineSectionsCharCounts = includedSections.map((section) => ({
      type: section.type ?? null,
      charCount: getCharCount(section.content ?? ''),
    }));
    const baselineContentHash =
      baselineVersion.hash ?? baseline.hash ?? sha256(baselineTextForDebug);

    const calibration = await this.getCalibration(userId);
    const dimensionWeights = this.mapCalibrationToDimensionWeights(
      calibration.weights,
    );

    const jobInput = payload.job ?? {};
    const jobId = jobInput.id?.trim();
    const baselineVersionHash = baseline.hash ?? null;
    const allowDebug = Boolean(payload.debug);

    let job: Job | null = null;
    let jobPayload: {
      title: string | null;
      company: string | null;
      rawDescription: string;
      normalizedResponsibilities: string[];
      normalizedRequirements: string[];
      sourceUrl: string | null;
    };

    if (jobId) {
      job = await this.jobRepository.findOne({
        where: { id: jobId, userId },
      });

      if (!job) {
        throw new NotFoundException('Job not found');
      }

      jobPayload = {
        title: job.title ?? null,
        company: job.company ?? null,
        rawDescription: job.rawDescription,
        normalizedResponsibilities: job.normalizedResponsibilities ?? [],
        normalizedRequirements: job.normalizedRequirements ?? [],
        sourceUrl: job.sourceUrl ?? null,
      };
    } else {
      const rawText = jobInput.raw_jd_text ?? jobInput.raw_jd;
      const hasParsed = jobInput.parsed_jd !== undefined;
      jobPayload = hasParsed
        ? this.buildJobPayloadFromParsed(jobInput)
        : {
            title: null,
            company: null,
            rawDescription: rawText ?? '',
            normalizedResponsibilities: [],
            normalizedRequirements: [],
            sourceUrl: null,
          };
    }

    const { canonicalJobForScoring, canonicalJobForHash, jobTextForScoring } =
      this.buildCanonicalJobAssets(jobPayload);

    const normalizedResponsibilities =
      canonicalJobForHash.normalizedResponsibilities;
    const normalizedRequirements = canonicalJobForHash.normalizedRequirements;
    const normalizedResponsibilitiesStats = this.buildNormalizedSegmentStats(
      normalizedResponsibilities,
    );
    const normalizedRequirementsStats = this.buildNormalizedSegmentStats(
      normalizedRequirements,
    );
    const normalizedJobDescription = this.complianceService.normalizeText(
      canonicalJobForHash.rawDescription,
    );

    if (jobTextForScoring.jobRawTextTooShort) {
      console.warn(
        `Raw job description for job ${job?.id ?? jobId ?? 'ad-hoc'} is only ${jobTextForScoring.jobRawTextCharCount} characters (<${RAW_TEXT_WARNING_THRESHOLD.toLocaleString()}).`,
      );
    }

    const chosenText = jobTextForScoring.jobText;
    const chosenTextChars = getCharCount(chosenText);

    const jobSource =
      job?.jdIngestionMethod === JobIngestionMethod.URL ||
      job?.jdIngestionMethod === JobIngestionMethod.SOURCE_PROVIDER ||
      Boolean(jobPayload.sourceUrl)
        ? 'url'
        : job?.jdIngestionMethod === JobIngestionMethod.PASTE
          ? 'paste'
          : canonicalJobForHash.rawDescription
            ? 'paste'
            : 'unknown';

    const baselineForHash: Baseline = {
      ...baseline,
      sections: filteredSections,
      version: baselineVersion.versionNumber ?? baseline.version,
    };
    const inputsHash = this.buildInputsHash(
      canonicalJobForHash,
      baselineForHash,
      dimensionWeights,
    );

    const scoring = await this.fitScoringService.score(
      {
        job: canonicalJobForScoring,
        baseline: {
          version: baselineVersion.versionNumber ?? baseline.version ?? null,
          sections: sectionPayload,
        },
      },
      dimensionWeights,
      { debug: allowDebug },
    );

    const scoringV2 = scoreCxFitV2({
      job: jobPayload,
      baselineSections: includedSections,
    });

    const debugInfo: CompatibilityRunDebugPayload | undefined = allowDebug
      ? this.buildCompatibilityDebugPayload({
          baselineId: baseline.id,
          baselineVersionHash,
          baselineSelectedSectionCount: includedSections.length,
          baselineTotalChars: baselineTextCharsScored,
          jobId: job?.id ?? jobId ?? null,
          jobRawChars: jobTextForScoring.jobRawTextCharCount,
          normalizedResponsibilitiesCount:
            normalizedResponsibilitiesStats.count,
          normalizedResponsibilitiesChars:
            normalizedResponsibilitiesStats.chars,
          normalizedRequirementsCount: normalizedRequirementsStats.count,
          normalizedRequirementsChars: normalizedRequirementsStats.chars,
          dimensionScores: scoring.dimensionScores,
          totalScore: scoring.overallScore,
          jobRawTextCharCount: jobTextForScoring.jobRawTextCharCount,
          jobRawTextSha256: jobTextForScoring.jobRawTextSha256,
          jobRawTextTooShort: jobTextForScoring.jobRawTextTooShort,
          jobRawTextWarning: jobTextForScoring.jobRawTextWarning,
          jobTextSource: jobTextForScoring.jobTextSource,
        })
      : undefined;

    const generatedSectionsForCompliance = normalizedJobDescription
      ? [{ title: 'Job Description', content: normalizedJobDescription }]
      : undefined;

    let savedAssessment: FitAssessment | null = null;

    if (job) {
      const assessment = this.fitAssessmentRepository.create({
        userId,
        jobId: job.id,
        baselineId: baseline.id,
        baselineVersion:
          baselineVersion.versionNumber ?? baseline.version ?? null,
        overallScore: scoring.overallScore,
        verdict: scoring.persistenceVerdict ?? FitAssessmentVerdict.CONSIDER,
        dimensionScores: scoring.dimensionScores,
        strengths: scoring.strengths,
        gaps: scoring.gaps,
        complianceFlags: scoring.complianceFlags,
        inputsHash,
      });

      savedAssessment = await this.fitAssessmentRepository.save(assessment);
    }

    const compliance = await this.complianceService.validateAndAudit({
      action: ComplianceAction.FIT_SCORE,
      actorId: userId,
      baselineVersion,
      job: job ?? null,
      outputHash: inputsHash,
      baselineSections: complianceBaselineSections,
      generatedSections: generatedSectionsForCompliance,
      extraFlags: this.mapComplianceStringsToFlags(scoring.complianceFlags),
    });

    if (compliance.blocked) {
      throw new BadRequestException({
        error: {
          code: 'compliance_blocked',
          message: 'Compliance validation failed.',
          details: { compliance_flags: compliance.complianceFlags },
        },
      });
    }

    const breakdown = {
      experience_alignment: scoring.dimensionScores.experienceAlignment,
      leadership_level: scoring.dimensionScores.leadershipLevel,
      technical_platform_fit: scoring.dimensionScores.technicalPlatformFit,
      industry_context: scoring.dimensionScores.industryContext,
      strategic_vs_tactical: scoring.dimensionScores.strategicTacticalFit,
    };

    const scoringProof: ScoringProofSnapshot = {
      assessmentId: null,
      baselineTextCharsScored: baselineExtractedTextChars,
      jobTextCharsScored: chosenTextChars,
      truncationAppliedBaseline: false,
      truncationAppliedJob: false,
      normalizedResponsibilitiesCount: normalizedResponsibilities.length,
      normalizedRequirementsCount: normalizedRequirements.length,
      jobRawTextCharCount: jobTextForScoring.jobRawTextCharCount,
      jobRawTextSha256: jobTextForScoring.jobRawTextSha256,
      jobRawTextTooShort: jobTextForScoring.jobRawTextTooShort,
      jobRawTextWarning: jobTextForScoring.jobRawTextWarning,
      jobTextSource: jobTextForScoring.jobTextSource,
    };

    return {
      fit_score: scoring.overallScore,
      overall_score: scoring.overallScore,
      verdict: scoring.verdict ?? 'consider',
      breakdown,
      strengths: scoring.strengths,
      gaps: scoring.gaps,
      compliance_flags: this.coerceComplianceFlags(scoring.complianceFlags),
      audit_id: compliance.audit.id,
      auditId: compliance.audit.id,
      assessmentId: savedAssessment?.id,
      jobId: savedAssessment?.jobId,
      baselineId: savedAssessment?.baselineId,
      baselineVersion: savedAssessment?.baselineVersion,
      createdAt: savedAssessment?.createdAt,
      scoring_v2: scoringV2,
      score: scoringV2.score,
      overallScore: scoring.overallScore,
      dimensionScores: scoring.dimensionScores,
      complianceFlags: scoring.complianceFlags,
      summary: scoring.summary,
      ...(debugInfo ? { debug: debugInfo } : {}),
      scoringProof,
    };
  }

  async analyzeForUser(
    userId: string,
    payload: AnalysisRequest,
  ): Promise<AnalysisResult> {
    const baselineId = payload.baselineId?.trim();
    if (!baselineId) {
      throw new BadRequestException('baselineId is required');
    }

    const hasJobId = Boolean(payload.jobId?.trim());
    const hasJobDescription = Boolean(payload.jobDescription?.trim());

    if (!hasJobId && !hasJobDescription) {
      throw new BadRequestException('jobId or jobDescription is required');
    }

    const baseline = await this.baselineRepository.findOne({
      where: { id: baselineId, userId },
      relations: ['sections'],
      order: { sections: { order: 'ASC' } },
    });

    if (!baseline) {
      throw new NotFoundException('Baseline not found');
    }

    if (!baseline.sections?.length) {
      baseline.sections = await this.baselineSectionRepository.find({
        where: { baselineId: baseline.id },
        order: { order: 'ASC' },
      });
    }

    const includedSections =
      baseline.sections?.filter(
        (section) => section.includePolicy !== BaselineIncludePolicy.NEVER,
      ) ?? [];

    const complianceBaselineSections =
      this.complianceService.normalizeSectionsForOutput(includedSections);

    const jobId = payload.jobId?.trim();
    const job = jobId
      ? await this.jobRepository.findOne({
          where: { id: jobId, userId },
        })
      : null;
    const jobDescription = job
      ? job.rawDescription
      : payload.jobDescription?.trim();

    if (!jobDescription) {
      throw new NotFoundException('Job not found');
    }

    const normalizedJobDescription =
      this.complianceService.normalizeText(jobDescription);
    const jobRawChars = getCharCount(jobDescription);
    const jobRawTextTooShort = jobRawChars > 0 && jobRawChars < 3000;
    if (jobRawTextTooShort) {
      console.warn(
        `Raw job description for baseline ${baselineId} is only ${jobRawChars} characters (<3,000).`,
      );
    }

    const baselineText = this.buildBaselineText(includedSections);
    const baselineKeywords = this.normalizeKeywords(baselineText);
    const jobKeywords = this.normalizeKeywords(jobDescription);

    const baselineSet = new Set(baselineKeywords.keys());
    const jobSet = new Set(jobKeywords.keys());

    const overlap = [...jobSet].filter((keyword) => baselineSet.has(keyword));
    const gaps = [...jobSet].filter((keyword) => !baselineSet.has(keyword));

    const overlapSorted = this.sortByFrequency(jobKeywords, overlap);
    const gapsSorted = this.sortByFrequency(jobKeywords, gaps);

    const total = jobSet.size;
    const matched = overlap.length;
    const score = total === 0 ? 0 : Math.round((matched / total) * 100);

    const strengths = overlapSorted.slice(0, 8);
    const gapList = gapsSorted.slice(0, 8);

    const summary =
      total === 0
        ? 'No keywords found in the job description.'
        : `Matched ${matched} of ${total} key terms from the job description.`;

    const generatedSectionsForCompliance = normalizedJobDescription
      ? [{ title: 'Job Description', content: normalizedJobDescription }]
      : undefined;

    const outputHash = sha256(
      `${baseline.hash ?? ''}:${normalizedJobDescription}`,
    );

    const compliance = await this.complianceService.validateAndAudit({
      action: ComplianceAction.FIT_SCORE,
      actorId: userId,
      baselineVersion: { hash: baseline.hash } as BaselineVersion,
      job,
      outputHash,
      baselineSections: complianceBaselineSections,
      generatedSections: generatedSectionsForCompliance,
    });

    if (compliance.blocked) {
      throw new BadRequestException({
        error: {
          code: 'compliance_blocked',
          message: 'Compliance validation failed.',
          details: { compliance_flags: compliance.complianceFlags },
        },
      });
    }

    return {
      ok: true,
      baselineId: baseline.id,
      score,
      strengths,
      gaps: gapList,
      summary,
      compliance_flags: this.coerceComplianceFlags(compliance.complianceFlags),
      audit_id: compliance.audit.id,
      auditId: compliance.audit.id,
      baseline_version_hash:
        compliance.audit.baselineVersionHash ?? baseline.hash ?? null,
    };
  }

  async runFitAssessment(userId: string, payload: RunFitAssessmentDto) {
    const baselineId = payload.baselineId?.trim();
    const jobId = payload.jobId?.trim();

    if (!baselineId || !jobId) {
      throw new BadRequestException('baselineId and jobId are required');
    }

    if (payload.baselineVersion !== undefined) {
      const version = Number(payload.baselineVersion);
      if (!Number.isInteger(version) || version < 1) {
        throw new BadRequestException(
          'baselineVersion must be a positive integer',
        );
      }
    }

    const baseline = await this.baselineRepository.findOne({
      where: { id: baselineId, userId },
      relations: ['sections'],
      order: { sections: { order: 'ASC' } },
    });

    if (!baseline) {
      throw new NotFoundException('Baseline not found');
    }

    if (!baseline.sections?.length) {
      baseline.sections = await this.baselineSectionRepository.find({
        where: { baselineId: baseline.id },
        order: { order: 'ASC' },
      });
    }

    const job = await this.jobRepository.findOne({
      where: { id: jobId, userId },
    });

    if (!job) {
      throw new NotFoundException('Job not found');
    }

    const filteredSections = this.getIncludedSections(baseline.sections);
    const includedSections = filteredSections.map((section) => ({
      type: section.sectionType ?? section.type,
      content: section.content,
    }));
    const sectionPayload = includedSections;

    const baselineVersionValue =
      payload.baselineVersion ?? baseline.version ?? 0;
    const baselineForHash: Baseline = {
      ...baseline,
      sections: filteredSections,
      version: baselineVersionValue,
    };

    const complianceBaselineSections =
      this.complianceService.normalizeSectionsForOutput(includedSections);

    const baselineProofText = includedSections
      .map((section) => section.content ?? '')
      .join('\n');
    const baselineTextCharsScored = getCharCount(baselineProofText);

    const { canonicalJobForScoring, canonicalJobForHash, jobTextForScoring } =
      this.buildCanonicalJobAssets({
        rawDescription: job.rawDescription,
        normalizedResponsibilities: job.normalizedResponsibilities ?? [],
        normalizedRequirements: job.normalizedRequirements ?? [],
        title: job.title ?? null,
        company: job.company ?? null,
        sourceUrl: job.sourceUrl ?? null,
      });

    const normalizedResponsibilities =
      canonicalJobForHash.normalizedResponsibilities;
    const normalizedRequirements = canonicalJobForHash.normalizedRequirements;
    const normalizedResponsibilitiesStats = this.buildNormalizedSegmentStats(
      normalizedResponsibilities,
    );
    const normalizedRequirementsStats = this.buildNormalizedSegmentStats(
      normalizedRequirements,
    );

    if (jobTextForScoring.jobRawTextTooShort) {
      console.warn(
        `Raw job description for job ${job.id} is only ${jobTextForScoring.jobRawTextCharCount} characters (<${RAW_TEXT_WARNING_THRESHOLD.toLocaleString()}).`,
      );
    }

    const jobTextCharsScored = getCharCount(jobTextForScoring.jobText);

    const scoringProofBase = {
      baselineTextCharsScored,
      jobTextCharsScored,
      truncationAppliedBaseline: false,
      truncationAppliedJob: false,
      normalizedResponsibilitiesCount: normalizedResponsibilities.length,
      normalizedRequirementsCount: normalizedRequirements.length,
      jobRawTextCharCount: jobTextForScoring.jobRawTextCharCount,
      jobRawTextSha256: jobTextForScoring.jobRawTextSha256,
      jobRawTextTooShort: jobTextForScoring.jobRawTextTooShort,
      jobRawTextWarning: jobTextForScoring.jobRawTextWarning,
      jobTextSource: jobTextForScoring.jobTextSource,
    };

    const calibration = await this.getCalibration(userId);

    const dimensionWeights = this.mapCalibrationToDimensionWeights(
      calibration.weights,
    );
    const inputsHash = this.buildInputsHash(
      canonicalJobForHash,
      baselineForHash,
      dimensionWeights,
    );
    const allowDebug = Boolean(payload.debug);

    const scoring = await this.fitScoringService.score(
      {
        job: canonicalJobForScoring,
        baseline: {
          version: baseline.version ?? null,
          sections: sectionPayload,
        },
      },
      dimensionWeights,
    );

    const generatedSectionsForCompliance = scoring.summary
      ? [{ title: 'Fit scoring summary', content: scoring.summary }]
      : undefined;

    const compliance = await this.complianceService.validateAndAudit({
      action: ComplianceAction.FIT_SCORE,
      actorId: userId,
      baselineVersion: { hash: baseline.hash } as BaselineVersion,
      job,
      outputHash: inputsHash,
      baselineSections: complianceBaselineSections,
      generatedSections: generatedSectionsForCompliance,
      extraFlags: this.mapComplianceStringsToFlags(scoring.complianceFlags),
    });

    if (compliance.blocked) {
      throw new BadRequestException({
        error: {
          code: 'compliance_blocked',
          message: 'Compliance validation failed.',
          details: { compliance_flags: compliance.complianceFlags },
        },
      });
    }

    const assessment = this.fitAssessmentRepository.create({
      userId,
      jobId,
      baselineId: baseline.id,
      baselineVersion: payload.baselineVersion ?? baseline.version ?? null,
      overallScore: scoring.overallScore,
      verdict: scoring.persistenceVerdict ?? FitAssessmentVerdict.CONSIDER,
      dimensionScores: scoring.dimensionScores,
      strengths: scoring.strengths,
      gaps: scoring.gaps,
      complianceFlags: scoring.complianceFlags,
      inputsHash,
    });

    const baselineVersionHash = baseline.hash ?? null;
    const jobIdentifier = job?.id ?? jobId ?? null;
    const debugInfo: CompatibilityRunDebugPayload | undefined = allowDebug
      ? this.buildCompatibilityDebugPayload({
          baselineId: baseline.id,
          baselineVersionHash,
          baselineSelectedSectionCount: includedSections.length,
          baselineTotalChars: baselineTextCharsScored,
          jobId: jobIdentifier,
          jobRawChars: jobTextForScoring.jobRawTextCharCount,
          normalizedResponsibilitiesCount:
            normalizedResponsibilitiesStats.count,
          normalizedResponsibilitiesChars:
            normalizedResponsibilitiesStats.chars,
          normalizedRequirementsCount: normalizedRequirementsStats.count,
          normalizedRequirementsChars: normalizedRequirementsStats.chars,
          dimensionScores: scoring.dimensionScores,
          totalScore: scoring.overallScore,
          jobRawTextCharCount: jobTextForScoring.jobRawTextCharCount,
          jobRawTextSha256: jobTextForScoring.jobRawTextSha256,
          jobRawTextTooShort: jobTextForScoring.jobRawTextTooShort,
          jobRawTextWarning: jobTextForScoring.jobRawTextWarning,
          jobTextSource: jobTextForScoring.jobTextSource,
        })
      : undefined;

    const saved = await this.fitAssessmentRepository.save(assessment);
    return {
      ok: true,
      assessmentId: saved.id,
      jobId: saved.jobId,
      baselineId: saved.baselineId,
      baselineVersion: saved.baselineVersion,
      overallScore: saved.overallScore,
      score: saved.overallScore,
      verdict: saved.verdict,
      dimensionScores: saved.dimensionScores,
      strengths: saved.strengths,
      gaps: saved.gaps,
      complianceFlags: saved.complianceFlags,
      summary: scoring.summary,
      audit_id: compliance.audit.id,
      auditId: compliance.audit.id,
      ...(debugInfo ? { debug: debugInfo } : {}),
      scoringProof: {
        ...scoringProofBase,
        assessmentId: saved.id,
      },
      baseline_version_hash:
        compliance.audit.baselineVersionHash ?? baseline.hash ?? null,
      createdAt: saved.createdAt,
    };
  }

  async runExpandedFitAssessment(
    userId: string,
    payload: RunExpandedFitAssessmentDto,
  ) {
    const baselineId = payload.baselineId?.trim();
    const jobId = payload.jobId?.trim();

    if (!baselineId || !jobId) {
      throw new BadRequestException('baselineId and jobId are required');
    }

    if (payload.baselineVersion !== undefined) {
      const version = Number(payload.baselineVersion);
      if (!Number.isInteger(version) || version < 1) {
        throw new BadRequestException(
          'baselineVersion must be a positive integer',
        );
      }
    }

    const baseline = await this.baselineRepository.findOne({
      where: { id: baselineId, userId },
      relations: ['sections'],
      order: { sections: { order: 'ASC' } },
    });

    if (!baseline) {
      throw new NotFoundException('Baseline not found');
    }

    if (!baseline.sections?.length) {
      baseline.sections = await this.baselineSectionRepository.find({
        where: { baselineId: baseline.id },
        order: { order: 'ASC' },
      });
    }

    const job = await this.jobRepository.findOne({
      where: { id: jobId, userId },
    });

    if (!job) {
      throw new NotFoundException('Job not found');
    }

    const interviewId = payload.interviewId?.trim();
    const interview = interviewId
      ? await this.interviewRepository.findOne({
          where: { id: interviewId, userId },
        })
      : null;

    if (interviewId && !interview) {
      throw new NotFoundException('Interview not found');
    }

    const additionsFromPayload = this.normalizeAdditions(
      payload.verifiedAdditions,
    );
    const additions = additionsFromPayload.length
      ? additionsFromPayload
      : this.normalizeAdditions(interview?.recommendedAdditions);

    if (!additions.length) {
      throw new BadRequestException(
        'verified additions are required for expanded scoring',
      );
    }

    const includedSections =
      baseline.sections?.filter(
        (section) => section.includePolicy !== BaselineIncludePolicy.NEVER,
      ) ?? [];

    const baselineVersionValue =
      payload.baselineVersion ?? baseline.version ?? 0;
    const baselineForHash: Baseline = {
      ...baseline,
      sections: includedSections,
      version: baselineVersionValue,
    };

    const complianceBaselineSections =
      this.complianceService.normalizeSectionsForOutput(includedSections);

    const calibration = await this.getCalibration(userId);
    const dimensionWeights = this.mapCalibrationToDimensionWeights(
      calibration.weights,
    );

    const sectionPayload = includedSections.map((section) => ({
      type: section.sectionType ?? section.type,
      content: section.content,
    }));

    const { canonicalJobForScoring, canonicalJobForHash, jobTextForScoring } =
      this.buildCanonicalJobAssets({
        rawDescription: job.rawDescription,
        normalizedResponsibilities: job.normalizedResponsibilities ?? [],
        normalizedRequirements: job.normalizedRequirements ?? [],
        title: job.title ?? null,
        company: job.company ?? null,
        sourceUrl: job.sourceUrl ?? null,
      });

    if (jobTextForScoring.jobRawTextTooShort) {
      console.warn(
        `Raw job description for job ${job.id} is only ${jobTextForScoring.jobRawTextCharCount} characters (<${RAW_TEXT_WARNING_THRESHOLD.toLocaleString()}).`,
      );
    }

    const inputsHash = this.buildInputsHash(
      canonicalJobForHash,
      baselineForHash,
      dimensionWeights,
    );

    const scoring = await this.fitScoringService.score(
      {
        job: canonicalJobForScoring,
        baseline: {
          version: payload.baselineVersion ?? baseline.version ?? null,
          sections: sectionPayload,
        },
        verifiedAdditions: additions,
      },
      dimensionWeights,
    );

    const additionsForCompliance = additions.map((addition, index) => ({
      title: `Verified addition ${index + 1}`,
      content: this.complianceService.normalizeText(addition),
    }));

    const generatedSectionsForCompliance = additionsForCompliance.length
      ? additionsForCompliance
      : undefined;

    const compliance = await this.complianceService.validateAndAudit({
      action: ComplianceAction.FIT_SCORE,
      actorId: userId,
      baselineVersion: { hash: baseline.hash } as BaselineVersion,
      job,
      outputHash: inputsHash,
      baselineSections: complianceBaselineSections,
      generatedSections: generatedSectionsForCompliance,
      extraFlags: this.mapComplianceStringsToFlags(scoring.complianceFlags),
    });

    if (compliance.blocked) {
      throw new BadRequestException({
        error: {
          code: 'compliance_blocked',
          message: 'Compliance validation failed.',
          details: { compliance_flags: compliance.complianceFlags },
        },
      });
    }

    const linkedAssessment = await this.fitAssessmentRepository.findOne({
      where: { userId, jobId, baselineId },
      order: { createdAt: 'DESC' },
    });

    const expansion = this.expandedFitAssessmentRepository.create({
      userId,
      jobId,
      baselineId,
      baselineVersion: payload.baselineVersion ?? baseline.version ?? null,
      fitAssessmentId: linkedAssessment?.id ?? undefined,
      interviewId: interview?.id ?? undefined,
      originalScore: scoring.originalScore,
      expandedScore: scoring.expandedScore,
      delta: scoring.delta,
      additions,
      expandedDimensionScores:
        scoring.expandedDimensionScores ?? scoring.dimensionScores,
    });

    const savedExpansion =
      await this.expandedFitAssessmentRepository.save(expansion);

    return {
      ok: true,
      expansionId: savedExpansion.id,
      fitAssessmentId: linkedAssessment?.id ?? null,
      interviewId: interview?.id ?? null,
      baselineId,
      baselineVersion: payload.baselineVersion ?? baseline.version ?? null,
      jobId,
      originalScore: scoring.originalScore,
      expandedScore: scoring.expandedScore,
      delta: scoring.delta,
      expandedDimensionScores:
        scoring.expandedDimensionScores ?? scoring.dimensionScores,
      dimensionScores: scoring.dimensionScores,
      strengths: scoring.strengths,
      gaps: scoring.gaps,
      complianceFlags: scoring.complianceFlags,
      appliedAdditions: scoring.appliedAdditions,
      summary: scoring.summary,
      audit_id: compliance.audit.id,
      auditId: compliance.audit.id,
      baseline_version_hash:
        compliance.audit.baselineVersionHash ?? baseline.hash ?? null,
    };
  }

