import {
  BadRequestException,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcryptjs';
import { UsersService } from '../users/users.service';
import { LoginDto } from './dto/login.dto';
import { RegisterDto } from './dto/register.dto';
import { User } from '../users/user.entity';
import { getEntitlementsForTier } from '../features/feature-gates';
import type { AuthResponseDto } from './dto/auth-response.dto';

@Injectable()
export class AuthService {
  constructor(
    private readonly usersService: UsersService,
    private readonly jwtService: JwtService,
  ) {}

  async register(payload: RegisterDto): Promise<AuthResponseDto> {
    const existing = await this.usersService.findByEmail(payload.email);

    if (existing) {
      throw new BadRequestException('Email already registered');
    }

    const passwordHash = await bcrypt.hash(payload.password, 10);
    const user = await this.usersService.create(payload.email, passwordHash);

    return this.buildAuthResponse(user);
  }

  async login(payload: LoginDto): Promise<AuthResponseDto> {
    const user = await this.usersService.findByEmail(payload.email);

    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const isValidPassword = await bcrypt.compare(
      payload.password,
      user.passwordHash,
    );

    if (!isValidPassword) {
      throw new UnauthorizedException('Invalid credentials');
    }

    return this.buildAuthResponse(user);
  }

  private buildAuthResponse(user: User): AuthResponseDto {
    const entitlements = getEntitlementsForTier(user.subscriptionTier);

    const payload = {
      sub: user.id,
      email: user.email,
      subscriptionTier: user.subscriptionTier,
      entitlements,
    };

    const accessToken = this.jwtService.sign(payload);

    const { passwordHash, ...sanitizedUser } = user;

    return {
      accessToken,
      user: { ...sanitizedUser, entitlements },
    };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UsersService } from '../users/users.service';
import { getEntitlementsForTier } from '../features/feature-gates';
import type { AuthUserDto } from './dto/auth-response.dto';
import type { Request } from 'express';

type JwtPayload = {
  sub: string;
  email: string;
  subscriptionTier?: string;
};

const AUTH_COOKIE_NAME = 'ttr_token';

function extractTokenFromCookie(
  req: Request | undefined | null,
): string | null {
  if (!req) {
    return null;
  }

  const cookieHeader = req.headers?.cookie;
  if (!cookieHeader) {
    return null;
  }

  const parts = cookieHeader.split(';');
  for (const part of parts) {
    const trimmed = part.trim();
    if (!trimmed) continue;
    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex <= 0) continue;
    const name = trimmed.slice(0, separatorIndex).trim();
    if (name !== AUTH_COOKIE_NAME) continue;
    const value = trimmed.slice(separatorIndex + 1);
    return value ? decodeURIComponent(value) : null;
  }

  return null;
}

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    configService: ConfigService,
    private readonly usersService: UsersService,
  ) {
    const jwtSecret = configService.get<string>('JWT_SECRET');

    if (!jwtSecret) {
      // Fail fast if misconfigured instead of letting it be undefined
      throw new Error('JWT_SECRET is not configured');
    }

    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        ExtractJwt.fromAuthHeaderAsBearerToken(),
        extractTokenFromCookie,
      ]),
      ignoreExpiration: false,
      secretOrKey: jwtSecret,
    });
  }

  async validate(payload: JwtPayload): Promise<AuthUserDto> {
    const user = await this.usersService.findById(payload.sub);

    if (!user) {
      throw new UnauthorizedException('User not found');
    }

    const entitlements = getEntitlementsForTier(user.subscriptionTier);

    const { passwordHash, ...sanitizedUser } = user;

    return {
      ...sanitizedUser,
      entitlements,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import type { Express } from 'express';
import * as mammoth from 'mammoth';
import pdf from 'pdf-parse';

@Injectable()
export class BaselineTextExtractor {
  private readonly logger = new Logger(BaselineTextExtractor.name);

  async extractText(file: Express.Multer.File): Promise<string> {
    const buffer = await this.readFileBuffer(file);
    const extension = path
      .extname(file.originalname || file.path || '')
      .toLowerCase();
    const mimetype = (file.mimetype || '').toLowerCase();

    try {
      if (
        extension === '.docx' ||
        mimetype ===
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      ) {
        return await this.extractDocx(buffer);
      }

      if (extension === '.pdf' || mimetype === 'application/pdf') {
        return await this.extractPdf(buffer);
      }
    } catch (error) {
      this.logger.error(
        'Failed to extract text from uploaded file',
        (error as Error)?.stack,
      );
    }

    return this.fallbackToUtf8(buffer);
  }

  private async extractDocx(buffer: Buffer): Promise<string> {
    const result = await mammoth.extractRawText({ buffer });
    return result.value;
  }

  private async extractPdf(buffer: Buffer): Promise<string> {
    const result = await pdf(buffer);
    return result.text;
  }

  private async readFileBuffer(file: Express.Multer.File): Promise<Buffer> {
    if (file.buffer) {
      return file.buffer;
    }

    if (file.path) {
      return await readFile(file.path);
    }

    throw new Error('Unable to read uploaded file buffer');
  }

  private fallbackToUtf8(buffer: Buffer): string {
    return buffer.toString('utf8').replace(/\u0000/g, '');
  }
}

