      id: 's-1',
      baselineId: 'b-1',
      sectionType: BaselineSectionType.EXPERIENCE as any,
      title: null,
      content: 'Did important work.',
      includePolicy: BaselineIncludePolicy.OPTIONAL,
      order: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
    } as BaselineSection,
    {
      id: 's-2',
      baselineId: 'b-1',
      sectionType: BaselineSectionType.SKILLS as any,
      title: null,
      content: 'Typescript, leadership',
      includePolicy: BaselineIncludePolicy.OPTIONAL,
      order: 1,
      createdAt: new Date(),
      updatedAt: new Date(),
    } as BaselineSection,
  ];

  const baseline: Baseline = {
    id: 'b-1',
    userId: 'user-1',
    version: 1,
    originalFilename: 'resume.pdf',
    mimeType: 'application/pdf',
    storagePath: '/tmp/resume.pdf',
    hash: 'hash',
    sections,
    versions: [],
    createdAt: new Date(),
    updatedAt: new Date(),
  } as Baseline;

  const baselineVersion: BaselineVersion = {
    id: 'v-1',
    baselineId: 'b-1',
    versionNumber: 1,
    fileHash: 'hash-1',
    storagePath: '/tmp/resume.pdf',
    baseline,
    createdAt: new Date(),
