import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Patch,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import type { Request } from 'express';
import { InterviewsService } from './interviews.service';
import { CreateInterviewResponseDto } from './dto/create-interview-response.dto';

@Controller('interviews')
@UseGuards(AuthGuard('jwt'))
export class InterviewsController {
  constructor(private readonly interviewsService: InterviewsService) {}

  @Post()
  async createInterview(
    @Body() body: any,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.createInterview(userId, body);
  }

  @Get()
  async listInterviews(@Req() request: Request & { user?: { id?: string } }) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.listInterviewsForUser(userId);
  }

  @Get(':id')
  async getInterview(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.getInterviewForUser(id, userId);
  }

  @Post('start')
  async startInterviewFromFitReview(
    @Body() body: { jobId?: string; baselineId?: string },
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.startInterviewFromFitReview(userId, {
      jobId: body.jobId,
      baselineId: body.baselineId,
    });
  }

  @Patch(':id')
  async updateInterview(
    @Param('id') id: string,
    @Body() body: any,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.updateInterview(id, userId, body);
  }

  @Delete(':id')
  async deleteInterview(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.interviewsService.deleteInterview(id, userId);
  }

  @Post(':id/responses')
  async createInterviewResponse(
    @Param('id') id: string,
    @Body() body: { responses?: CreateInterviewResponseDto[] },
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    const responses = (body?.responses?.length ? body.responses : []).filter(
      (response): response is CreateInterviewResponseDto =>
        Boolean(response?.question && response?.response),
    );

    if (responses.length === 0) {
      throw new BadRequestException('No responses provided');
    }

    const createdResponses = await Promise.all(
      responses.map((response) =>
        this.interviewsService.createInterviewResponse(id, userId, response),
      ),
    );

    return createdResponses.length === 1
      ? createdResponses[0]
      : createdResponses;
  }
}

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { JobSourceFetchCacheService } from '../job-source-fetch-cache.service';
import { JobSourceHttpService } from '../job-source-http.service';
import { GreenhouseJobSourceProvider } from './greenhouse.provider';

const FIXTURE_DIR = join(__dirname, '../fixtures/greenhouse');
const listingHtml = readFileSync(join(FIXTURE_DIR, 'listing.html'), 'utf-8');
const headingHtml = readFileSync(
  join(FIXTURE_DIR, 'job-heading.html'),
  'utf-8',
);
const minimalHtml = readFileSync(
  join(FIXTURE_DIR, 'job-minimal.html'),
  'utf-8',
);

describe('GreenhouseJobSourceProvider', () => {
  const boardUrl = 'https://boards.greenhouse.io/example';
  const headingUrl = `${boardUrl}/jobs/123`;
  const minimalUrl = `${boardUrl}/jobs/minimal`;

  let provider: GreenhouseJobSourceProvider;
  let cache: JobSourceFetchCacheService;
  let httpService: JobSourceHttpService;
  let originalFetch: typeof globalThis.fetch | undefined;

  beforeAll(() => {
    originalFetch = (globalThis as any).fetch;
  });

  beforeEach(() => {
    cache = new JobSourceFetchCacheService();
    httpService = new JobSourceHttpService();
    provider = new GreenhouseJobSourceProvider(cache, httpService);
  });

  afterEach(() => {
    if (originalFetch) {
      (globalThis as any).fetch = originalFetch;
    } else {
      delete (globalThis as any).fetch;
    }

    jest.resetAllMocks();
  });

  it('extracts listings with external IDs from a board page', async () => {
    (globalThis as any).fetch = jest.fn(async (url: string) => {
      if (url === boardUrl) {
        return {
          ok: true,
          arrayBuffer: async () => Buffer.from(listingHtml),
        };
      }
      throw new Error('Unexpected fetch');
    });

    const listings = await provider.fetchListings({
      sourceType: 'GREENHOUSE' as any,
      sourceUrl: boardUrl,
    });

    const ids = listings.map((listing) => listing.externalId);
    expect(listings.length).toBe(3);
    expect(new Set(ids).size).toBe(3);
    expect(listings[0].title).toContain('Senior');
    expect(listings[0].url).toContain('/jobs/123');
  });

  it('limits listings when maxListings option is provided', async () => {
    (globalThis as any).fetch = jest.fn(async (url: string) => {
      if (url === boardUrl) {
        return {
          ok: true,
          arrayBuffer: async () => Buffer.from(listingHtml),
        };
      }
      throw new Error('Unexpected fetch');
    });

    const listings = await provider.fetchListings({
      sourceType: 'GREENHOUSE' as any,
      sourceUrl: boardUrl,
      options: { maxListings: 2 },
    });

    expect(listings).toHaveLength(2);
  });

  it('parses job detail with headings and bullets', () => {
    const parsed = provider.parseJob({
      url: headingUrl,
      html: headingHtml,
      fetchedAt: new Date(),
      metadata: { externalId: '123' },
    });

    expect(parsed.title).toContain('Senior Engineer');
    expect(parsed.company).toBe('Acme Corporation');
    expect(parsed.location).toBe('Remote');
    expect(parsed.descriptionText).toContain('Drive core platform');
    expect(parsed.responsibilities).toHaveLength(2);
    expect(parsed.requirements).toHaveLength(2);
    expect(parsed.applyUrl).toBe('https://boards.greenhouse.io/apply/123');
  });

  it('parses fallback structure when headings are missing', () => {
    const parsed = provider.parseJob({
      url: minimalUrl,
      html: minimalHtml,
      fetchedAt: new Date(),
      metadata: { externalId: 'minimal' },
    });

    expect(parsed.title).toContain('Junior Engineer');
    expect(parsed.responsibilities).toHaveLength(1);
    expect(parsed.requirements).toHaveLength(1);
    expect(parsed.applyUrl).toBe('https://boards.greenhouse.io/apply/minimal');
    expect(parsed.descriptionText).toContain('Support the product');
  });
});

import { BadRequestException, Injectable } from '@nestjs/common';
import { JobSourceFetchCacheService } from '../job-source-fetch-cache.service';
import { JobSourceHttpService } from '../job-source-http.service';
import { JobSourceProvider } from '../job-source.provider';
import {
  JobSourceInput,
  JobSourceListing,
  JobDetailRaw,
  ParsedJob,
} from '../job-source.types';
import { extractTextFromHtml } from '../../jobs/html-utils';

const RESPONSIBILITY_HEADINGS = [
  'responsibilities',
  'what you will do',
  'what you will be doing',
  'you will',
  'your impact',
];

const REQUIREMENT_HEADINGS = [
  'requirements',
  'qualifications',
  'you have',
  'what we need',
  'you bring',
];

@Injectable()
export class GreenhouseJobSourceProvider implements JobSourceProvider {
  readonly id = 'greenhouse';

  private readonly fetchOptions = {
    timeoutMs: 15_000,
    maxBytes: 1_000_000,
  };

  constructor(
    private readonly cache: JobSourceFetchCacheService,
    private readonly jobSourceHttp: JobSourceHttpService,
  ) {}

  canHandle(input: JobSourceInput): boolean {
    return input.sourceType === 'greenhouse';
  }

  async fetchListings(input: JobSourceInput): Promise<JobSourceListing[]> {
    const maxListings = this.normalizeMaxListings(input.options);
    const boardUrl = await this.resolveBoardUrl(input.sourceUrl);
    const html = await this.fetchBoardHtml(boardUrl);
    const listings = this.extractListingsFromHtml(html, boardUrl, maxListings);

    return listings;
  }

  async fetchJobDetail(listing: JobSourceListing): Promise<JobDetailRaw> {
    const html = await this.fetchBoardHtml(listing.url);

    return {
      url: listing.url,
      html,
      fetchedAt: new Date(),
      metadata: {
        externalId: listing.externalId,
      },
    };
  }

  parseJob(detail: JobDetailRaw): ParsedJob {
    const html = detail.html;
    const sanitized = extractTextFromHtml(html);
    const title = this.extractTitle(html, sanitized);
    const company =
      this.extractMetaContent(html, ['og:site_name', 'twitter:site']) ??
      this.extractLabelValue(sanitized, 'company');
    const location =
      this.extractLocationFromHtml(html, sanitized) ??
      this.extractLabelValue(sanitized, 'location');
    const descriptionText = sanitized;
    const { responsibilities, requirements } =
      this.extractResponsibilitiesAndRequirements(sanitized);
    const applyUrl = this.extractApplyUrl(html, detail.url) ?? detail.url;
    const externalId =
      detail.metadata?.externalId ?? this.extractExternalIdFromUrl(detail.url);

    if (!externalId) {
      throw new BadRequestException(
        'Greenhouse job detail missing identifier.',
      );
    }

    return {
      title,
      company,
      location,
      descriptionText,
      responsibilities,
      requirements,
      applyUrl,
      sourceUrl: detail.url,
      externalId: String(externalId),
    };
  }

  private async resolveBoardUrl(rawUrl: string): Promise<string> {
    const normalized = this.normalizeUrl(rawUrl);
    if (!normalized) {
      throw new BadRequestException('Invalid Greenhouse URL provided.');
    }

    const parsed = new URL(normalized);
    if (parsed.hostname.endsWith('greenhouse.io')) {
      return normalized;
    }

    const html = await this.fetchBoardHtml(normalized);
    const embedUrl = this.extractEmbedUrl(html);

    if (!embedUrl) {
      throw new BadRequestException(
        'Could not locate Greenhouse job board in provided page.',
      );
    }

    return embedUrl;
  }

  private extractListingsFromHtml(
    html: string,
    baseUrl: string,
    maxListings: number,
  ): JobSourceListing[] {
    const regex = /<a[^>]+href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    const seen = new Map<string, JobSourceListing>();
    let match: RegExpExecArray | null;

    while ((match = regex.exec(html)) && seen.size < maxListings) {
      const href = match[1];
      const url = this.normalizeHref(href, baseUrl);
      if (!url || !this.isGreenhouseJobUrl(url)) {
        continue;
      }

      const externalId = this.extractExternalIdFromUrl(url);
      if (!externalId || seen.has(externalId)) continue;

      const title =
        this.extractTextFromSnippet(match[2]) || `Job ${externalId}`;
      const location = this.extractLocationFromAnchor(match[0]);
      const postedAt = this.extractDateFromAnchorAttributes(match[0]);

      seen.set(externalId, {
        externalId,
        title,
        url,
        location,
        postedAt,
      });
    }

    return Array.from(seen.values());
  }

  private extractTextFromSnippet(snippet: string) {
    const stripped = extractTextFromHtml(snippet);
    return stripped ? stripped.trim() : null;
  }

  private extractDateFromAnchorAttributes(tag: string): Date | null {
    const match = tag.match(/data-posted=["']([^"']+)["']/i);
    if (match) {
      const parsed = new Date(match[1]);
      if (!Number.isNaN(parsed.getTime())) {
        return parsed;
      }
    }
    return null;
  }

  private extractLocationFromAnchor(tag: string): string | null {
    const match = tag.match(/data-location=["']([^"']+)["']/i);
    if (match) {
      return match[1].trim();
    }

    const ariaMatch = tag.match(/aria-label=["']([^"']+)["']/i);
    if (ariaMatch && ariaMatch[1]) {
      const parts = ariaMatch[1].split(',');
      if (parts.length > 1) {
        return parts[parts.length - 1].trim();
      }
    }

    return null;
  }

  private extractEmbedUrl(html: string): string | null {
    const iframeMatch = html.match(
      /<iframe[^>]+src=["']([^"']*boards\.greenhouse\.io[^"']*)["'][^>]*>/i,
    );
    if (iframeMatch) {
      return this.normalizeUrl(iframeMatch[1]) ?? null;
    }

    const linkMatch = html.match(
      /<a[^>]+href=["']([^"']*boards\.greenhouse\.io[^"']*)["'][^>]*>/i,
    );
    if (linkMatch) {
      return this.normalizeUrl(linkMatch[1]) ?? null;
    }

    return null;
  }

  private normalizeMaxListings(options?: Record<string, unknown> | null) {
    const raw = options?.['maxListings'];
    let candidate: number | null = null;
    if (typeof raw === 'number') {
      candidate = raw;
    } else if (typeof raw === 'string') {
      const parsed = Number(raw);
      if (!Number.isNaN(parsed)) {
        candidate = parsed;
      }
    }

    if (candidate && Number.isFinite(candidate)) {
      return Math.min(Math.max(1, Math.floor(candidate)), 200);
    }

    return 50;
  }

  private extractResponsibilitiesAndRequirements(text: string) {
    const lines = text
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line.length > 0);

    const responsibilities: string[] = [];
    const requirements: string[] = [];
    const fallback: string[] = [];
    let current: 'responsibilities' | 'requirements' | null = null;

    for (const line of lines) {
      const lower = line.toLowerCase();

      if (/^apply\b/.test(lower)) {
        current = null;
        continue;
      }

      if (RESPONSIBILITY_HEADINGS.some((heading) => lower.includes(heading))) {
        current = 'responsibilities';
        continue;
      }

      if (REQUIREMENT_HEADINGS.some((heading) => lower.includes(heading))) {
        current = 'requirements';
        continue;
      }

      const bulletMatch = line.match(/^[-•*]\s+(.*)/);
      if (bulletMatch) {
        const payload = bulletMatch[1].trim();
        fallback.push(payload);
        if (current === 'responsibilities') {
          responsibilities.push(payload);
        } else if (current === 'requirements') {
          requirements.push(payload);
        }
        continue;
      }

      if (current === 'responsibilities') {
        responsibilities.push(line);
      } else if (current === 'requirements') {
        requirements.push(line);
      }
    }

    if (!responsibilities.length && fallback.length) {
      responsibilities.push(
        ...fallback.slice(0, Math.ceil(fallback.length / 2)),
      );
    }

    if (!requirements.length && fallback.length) {
      requirements.push(...fallback.slice(Math.ceil(fallback.length / 2)));
    }

    return {
      responsibilities,
      requirements,
    };
  }

  private extractApplyUrl(html: string, baseUrl: string): string | null {
    const anchorRegex = /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    let match: RegExpExecArray | null;

    while ((match = anchorRegex.exec(html))) {
      const text = match[2];
      if (text && /apply/i.test(text)) {
        const normalized = this.normalizeHref(match[1], baseUrl);
        if (normalized) {
          return normalized;
        }
      }
    }

    const formMatch = html.match(/<form[^>]+action=["']([^"']+)["'][^>]*>/i);
    if (formMatch) {
      return this.normalizeHref(formMatch[1], baseUrl);
    }

    return null;
  }

  private extractTitle(html: string, sanitized: string): string {
    const headingMatch = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
    if (headingMatch) {
      return extractTextFromHtml(headingMatch[1]).trim();
    }

    const firstLine = sanitized
      .split('\n')
      .find((line) => line.trim().length > 0);
    return firstLine?.trim() ?? 'Greenhouse role';
  }

  private extractLocationFromHtml(
    html: string,
    sanitized: string,
  ): string | null {
    const locationMatch = html.match(/data-location=["']([^"']+)["']/i);
    if (locationMatch) {
      return locationMatch[1].trim();
    }

    const locationLine = sanitized
      .split('\n')
      .find((line) => /^location[:\s]/i.test(line));
    if (locationLine) {
      const parts = locationLine.split(/[:\-]/);
      if (parts.length > 1) {
        return parts.slice(1).join(':').trim();
      }
    }

    return null;
  }

  private extractLabelValue(text: string, label: string) {
    const match = text.match(new RegExp(`${label}[:\\s]+(.+)`, 'i'));
    if (match) {
      return match[1].trim();
    }
    return null;
  }

  private extractMetaContent(html: string, keys: string[]): string | null {
    for (const key of keys) {
      const regex = new RegExp(
        `<meta[^>]+property=["']${key}["'][^>]+content=["']([^"']+)["'][^>]*>`,
        'i',
      );
      const match = html.match(regex);
      if (match) {
        return match[1].trim();
      }
    }

    return null;
  }

  private extractExternalIdFromUrl(url: string): string | null {
    try {
      const parsed = new URL(url);
      const segments = parsed.pathname.split('/').filter(Boolean);
      const jobsIndex = segments.indexOf('jobs');
      const jobIndex = jobsIndex >= 0 ? jobsIndex + 1 : segments.length - 1;
      if (jobIndex >= 0 && jobIndex < segments.length) {
        return segments[jobIndex];
      }
    } catch {
      // ignore
    }
    return null;
  }

  private isGreenhouseJobUrl(url: string) {
    try {
      const parsed = new URL(url);
      return (
        parsed.hostname.includes('greenhouse.io') &&
        parsed.pathname.includes('/jobs/')
      );
    } catch {
      return false;
    }
  }

  private normalizeUrl(raw: string): string | null {
    try {
      const parsed = new URL(raw);
      if (!['http:', 'https:'].includes(parsed.protocol)) {
        return null;
      }
      return parsed.toString();
    } catch {
      return null;
    }
  }

  private normalizeHref(raw: string, base: string): string | null {
    try {
      const parsed = new URL(raw, base);
      if (!['http:', 'https:'].includes(parsed.protocol)) {
        return null;
      }
      return parsed.toString();
    } catch {
      return null;
    }
  }

  private async fetchBoardHtml(url: string): Promise<string> {
    const { value } = await this.cache.fetch(this.id, url, async () => {
      return this.jobSourceHttp.fetch(url, this.fetchOptions);
    });
    return value;
  }
}

import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Param,
  Patch,
  Post,
  Query,
  Req,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Request } from 'express';
import {
  CreateJobInput,
  IngestJobDescriptionInput,
  JobsService,
} from './jobs.service';
import { JobIngestionMethod } from './job.entity';

@Controller('jobs')
@UseGuards(AuthGuard('jwt'))
export class JobsController {
  constructor(private readonly jobsService: JobsService) {}

  @Post()
  async createJob(
    @Body() body: Partial<CreateJobInput>,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    const rawDescriptionInput = body.rawDescription;

    if (!rawDescriptionInput?.trim()) {
      throw new BadRequestException('Job description is required');
    }

    const result = await this.jobsService.createJob(userId, {
      title: body.title,
      company: body.company,
      rawDescription: rawDescriptionInput,
      sourceUrl: body.sourceUrl ?? null,
      responsibilities: body.responsibilities ?? undefined,
      requirements: body.requirements ?? undefined,
      jdIngestionMethod: body.jdIngestionMethod,
    });

    return {
      ...result.job,
      warning: result.warning ?? undefined,
    };
  }

  @Post('ingest')
  async ingestJobDescription(
    @Body() body: Partial<IngestJobDescriptionInput>,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.jobsService.ingestJobDescription({
      pastedText: body.pastedText,
      url: body.url,
    });
  }

  @Get()
  async listJobs(
    @Req() request: Request & { user?: { id?: string } },
    @Query('includeArchived') includeArchived?: string,
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    const include = includeArchived === 'true';
    return this.jobsService.listJobsForUser(userId, include);
  }

  @Patch(':id/archive')
  async archiveJob(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.jobsService.archiveJob(id, userId);
  }

  @Post(':id/archive')
  async archiveJobPost(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.jobsService.archiveJob(id, userId);
  }

  @Patch(':id/restore')
  async restoreJob(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.jobsService.restoreJob(id, userId);
  }

  @Get(':id')
  async getJob(
    @Param('id') id: string,
    @Req() request: Request & { user?: { id?: string } },
  ) {
    const userId = request.user?.id;

    if (!userId) {
      throw new BadRequestException('Invalid user context');
    }

    return this.jobsService.getJobForUser(id, userId);
  }
}

import { JobsService } from './jobs.service';

describe('JobsService', () => {
  const createService = () =>
    new JobsService({ create: jest.fn(), save: jest.fn() } as never);

  afterEach(() => {
    jest.restoreAllMocks();
    delete (global as any).fetch;
  });

  it('rejects localhost URLs during ingestion', async () => {
    const service = createService();

    await expect(
      service.ingestJobDescription({ url: 'http://localhost/job' }),
    ).rejects.toThrow('Job URLs hosted on private networks are not allowed.');
  });

  it('rejects private IP URLs during ingestion', async () => {
    const service = createService();

    await expect(
      service.ingestJobDescription({ url: 'https://10.0.0.5/role' }),
    ).rejects.toThrow('Job URLs hosted on private networks are not allowed.');
  });

  it('ingests job descriptions from a URL', async () => {
    const service = createService();
    const filler = 'A'.repeat(1100);
    const html = `
      <article>
        <h2>Responsibilities</h2>
        <ul><li>Build features</li></ul>
        <h2>Requirements</h2>
        <ul><li>5+ years</li></ul>
        <p>${filler}</p>
      </article>
    `;

    global.fetch = jest.fn().mockResolvedValue({
      status: 200,
      headers: {
        get: (key: string) =>
          key.toLowerCase() === 'content-type'
            ? 'text/html; charset=utf-8'
            : null,
      },
      arrayBuffer: async () => Buffer.from(html),
    } as never);

    const result = await service.ingestJobDescription({
      url: 'https://example.com/job',
    });

    expect(result.rawDescription.length).toBeGreaterThan(1000);
    expect(result.originalRawDescription.length).toBeGreaterThanOrEqual(
      result.rawDescription.length,
    );
    expect(result.responsibilities).toContain('Build features');
    expect(result.requirements).toContain('5+ years');
  });
});

import {
  BadRequestException,
  Injectable,
  NotFoundException,
  UnprocessableEntityException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { isIP } from 'node:net';
import { Repository } from 'typeorm';
import { Job, JobIngestionMethod } from './job.entity';
import { extractTextFromHtml } from './html-utils';
import { normalizeJobDescription, sanitizeListItems } from './jd-normalization';

export type CreateJobInput = {
  title?: string | null;
  company?: string | null;
  rawDescription: string;
  sourceUrl?: string | null;
  responsibilities?: string[];
  requirements?: string[];
  jdIngestionMethod?: JobIngestionMethod;
  sourceProviderId?: string | null;
  sourceExternalId?: string | null;
  canonicalUrl?: string | null;
  dedupeHash?: string | null;
};

export type IngestJobDescriptionInput = {
  pastedText?: string;
  url?: string;
};

export type IngestJobDescriptionResult = {
  rawDescription: string;
  originalRawDescription: string;
  responsibilities: string[];
  requirements: string[];
  warning?: JobWarning | null;
};

export type JobWarning = {
  status: number;
  code: string;
  message: string;
  details?: string | null;
};

export type CreateJobResult = {
  job: Job;
  warning?: JobWarning;
};

const MIN_DESCRIPTION_LENGTH = 1000;
const MAX_DESCRIPTION_LENGTH = 100000;
const MAX_HTML_BYTES = 1_000_000;
const FETCH_TIMEOUT_MS = 10_000;
const MAX_REDIRECTS = 4;
const JOB_LIMIT = 5;
const ALLOW_JOB_LIMIT_SKIP =
  process.env.NODE_ENV !== 'production' ||
  process.env.DISABLE_JOB_LIMIT === 'true';

const ALLOWED_CONTENT_TYPES = new Set(['text/html', 'text/plain']);
const PRIVATE_NETWORK_URL_ERROR =
  'Job URLs hosted on private networks are not allowed.';
const FETCH_TIMEOUT_MESSAGE = 'Job description request timed out.';
const FETCH_FAILURE_MESSAGE =
  'Unable to retrieve the job description from the provided URL.';
const CONTENT_TYPE_ERROR =
  'Job description content must be served as HTML or plain text.';
const NORMALIZATION_WARNING_MESSAGE =
  'We could not fully parse this job description, but it was saved successfully.';

@Injectable()
export class JobsService {
  constructor(
    @InjectRepository(Job)
    private readonly jobRepository: Repository<Job>,
  ) {}

  async ingestJobDescription(
    input: IngestJobDescriptionInput,
  ): Promise<IngestJobDescriptionResult> {
    const pastedText = input.pastedText?.trim();
    const url = input.url?.trim();
    const hasText = Boolean(pastedText);
    const hasUrl = Boolean(url);

    if (hasText === hasUrl) {
      throw new BadRequestException(
        'Provide exactly one of pastedText or url.',
      );
    }

    if (hasUrl) {
      const sanitizedUrl = this.validateUrl(url!);
      const html = await this.fetchHtml(sanitizedUrl);
      const extracted = extractTextFromHtml(html);
      const normalizedText = this.normalizeRawDescription(extracted);
      this.validateDescriptionLength(normalizedText);
      const normalizedOutcome = this.normalizeSafely(normalizedText);
      return {
        rawDescription: normalizedText,
        originalRawDescription: extracted,
        responsibilities: normalizedOutcome.responsibilities,
        requirements: normalizedOutcome.requirements,
        warning: normalizedOutcome.warning,
      };
    }

    const rawText = pastedText!;
    const normalizedText = this.normalizeRawDescription(rawText);
    this.validateDescriptionLength(normalizedText);
    const normalizedOutcome = this.normalizeSafely(normalizedText);

    return {
      rawDescription: normalizedText,
      originalRawDescription: rawText,
      responsibilities: normalizedOutcome.responsibilities,
      requirements: normalizedOutcome.requirements,
      warning: normalizedOutcome.warning,
    };
  }

  async createJob(
    userId: string,
    payload: CreateJobInput,
  ): Promise<CreateJobResult> {
    const originalRawDescription = payload.rawDescription;
    const normalizedInput = this.normalizeRawDescription(
      originalRawDescription,
    );
    this.validateDescriptionLength(normalizedInput);

    const normalizedOutcome = this.normalizeSafely(normalizedInput);
    const responsibilities =
      payload.responsibilities && payload.responsibilities.length > 0
        ? sanitizeListItems(payload.responsibilities)
        : normalizedOutcome.responsibilities;
    const requirements =
      payload.requirements && payload.requirements.length > 0
        ? sanitizeListItems(payload.requirements)
        : normalizedOutcome.requirements;

    const ingestionMethod =
      payload.jdIngestionMethod ?? JobIngestionMethod.PASTE;

    const allowedIngestionMethods = [
      JobIngestionMethod.PASTE,
      JobIngestionMethod.URL,
      JobIngestionMethod.SOURCE_PROVIDER,
    ];

    if (!allowedIngestionMethods.includes(ingestionMethod)) {
      throw new BadRequestException('Invalid jdIngestionMethod value');
    }

    const sourceUrl = payload.sourceUrl?.trim() || null;
    if (sourceUrl) {
      this.validateUrl(sourceUrl);
    }
    if (
      (ingestionMethod === JobIngestionMethod.URL ||
        ingestionMethod === JobIngestionMethod.SOURCE_PROVIDER) &&
      !sourceUrl
    ) {
      throw new BadRequestException(
        'sourceUrl is required for URL or provider ingestion.',
      );
    }

    const sourceProviderId = payload.sourceProviderId?.trim() || null;
    const sourceExternalId = payload.sourceExternalId?.trim() || null;
    const canonicalUrl = payload.canonicalUrl?.trim() || null;
    const dedupeHash = payload.dedupeHash?.trim() || null;

    await this.enforceJobLimit(userId);

    const job = this.jobRepository.create({
      userId,
      title: payload.title?.trim() || null,
      company: payload.company?.trim() || null,
      rawDescription: originalRawDescription,
      sourceUrl,
      sourceProviderId,
      sourceExternalId,
      canonicalUrl,
      dedupeHash,
      normalizedResponsibilities: responsibilities,
      normalizedRequirements: requirements,
      jdIngestionMethod: ingestionMethod,
      jdParsedAt: new Date(),
    });

    const savedJob = await this.jobRepository.save(job);
    return { job: savedJob, warning: normalizedOutcome.warning };
  }

  async listJobsForUser(userId: string, includeArchived = false) {
    const where = includeArchived ? { userId } : { userId, isArchived: false };

    return this.jobRepository.find({
      where,
      order: { createdAt: 'DESC' },
    });
  }

  async getJobForUser(id: string, userId: string) {
    return this.findJobForUser(id, userId);
  }

  async archiveJob(jobId: string, userId: string) {
    const job = await this.findJobForUser(jobId, userId);

    if (job.isArchived && job.archivedAt) {
      return job;
    }

    job.isArchived = true;
    job.archivedAt = new Date();

    return this.jobRepository.save(job);
  }

  async restoreJob(jobId: string, userId: string) {
    const job = await this.findJobForUser(jobId, userId);

    if (!job.isArchived && !job.archivedAt) {
      return job;
    }

    job.isArchived = false;
    job.archivedAt = null;

    return this.jobRepository.save(job);
  }

  private async findJobForUser(jobId: string, userId: string) {
    const job = await this.jobRepository.findOne({
      where: { id: jobId, userId },
    });

    if (!job) {
      throw new NotFoundException('Job not found');
    }

    return job;
  }

  private normalizeRawDescription(rawDescription: string) {
    const normalized = rawDescription
      .replace(/\r\n/g, '\n')
      .replace(/\r/g, '\n')
      .replace(/\t/g, ' ')
      .replace(/\u00a0/g, ' ')
      .split('\n')
      .map((line) => line.replace(/\s+/g, ' ').trim())
      .filter((line) => line.length > 0)
      .join('\n');

    return normalized.trim();
  }

  private validateDescriptionLength(description: string) {
    if (
      description.length < MIN_DESCRIPTION_LENGTH ||
      description.length > MAX_DESCRIPTION_LENGTH
    ) {
      throw new BadRequestException(
        'Job description must be between 1,000 and 100,000 characters.',
      );
    }
  }

  private async enforceJobLimit(userId: string) {
    const count = await this.jobRepository.count({ where: { userId } });

    if (ALLOW_JOB_LIMIT_SKIP) {
      return;
    }

    if (count >= JOB_LIMIT) {
      throw new UnprocessableEntityException({
        error: {
          code: 'limit_reached',
          entity: 'job',
          limit: JOB_LIMIT,
        },
      });
    }
  }

  private validateUrl(inputUrl: string) {
    let parsed: URL;
    try {
      parsed = new URL(inputUrl);
    } catch {
      throw new BadRequestException('Invalid URL provided.');
    }

    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new BadRequestException('Only http and https URLs are allowed.');
    }

    const normalizedHostname = normalizeHostname(parsed.hostname);
    if (
      isLocalHostname(normalizedHostname) ||
      isPrivateNetworkAddress(normalizedHostname)
    ) {
      throw new BadRequestException(PRIVATE_NETWORK_URL_ERROR);
    }

    return parsed.toString();
  }

  private async fetchHtml(url: string) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

    try {
      const response = await this.fetchWithRedirects(url, controller.signal);

      if (response.status < 200 || response.status >= 300) {
        throw new BadRequestException(FETCH_FAILURE_MESSAGE);
      }

      this.ensureAllowedContentType(response);

      const buffer = await response.arrayBuffer();
      if (buffer.byteLength > MAX_HTML_BYTES) {
        throw new BadRequestException('Job description response is too large.');
      }

      return Buffer.from(buffer).toString('utf-8');
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }

      if (
        error instanceof Error &&
        (error.name === 'AbortError' || (error as any)?.name === 'AbortError')
      ) {
        throw new BadRequestException(FETCH_TIMEOUT_MESSAGE);
      }

      throw new BadRequestException(FETCH_FAILURE_MESSAGE);
    } finally {
      clearTimeout(timeout);
    }
  }

  private ensureAllowedContentType(response: Response) {
    const contentType = (response.headers.get('content-type') ?? '')
      .split(';')[0]
      .trim()
      .toLowerCase();

    if (!contentType || !ALLOWED_CONTENT_TYPES.has(contentType)) {
      throw new BadRequestException(CONTENT_TYPE_ERROR);
    }
  }

  private async fetchWithRedirects(
    url: string,
    signal: AbortSignal,
  ): Promise<Response> {
    let currentUrl = url;
    let redirects = 0;

    while (true) {
      const safeUrl = this.validateUrl(currentUrl);
      const response = await fetch(safeUrl, {
        redirect: 'manual',
        signal,
      });

      const location =
        response.status >= 300 &&
        response.status < 400 &&
        response.headers.get('location');

      if (location) {
        if (redirects >= MAX_REDIRECTS) {
          throw new BadRequestException(
            'Too many redirects while fetching URL.',
          );
        }

        currentUrl = new URL(location, safeUrl).toString();
        redirects += 1;
        continue;
      }

      return response;
    }
  }

  private normalizeSafely(rawDescription: string): {
    responsibilities: string[];
    requirements: string[];
    warning?: JobWarning;
  } {
    try {
      const normalized = normalizeJobDescription(rawDescription);
      return {
        responsibilities: normalized.responsibilities,
        requirements: normalized.requirements,
      };
    } catch (error) {
      console.error('Job normalization failed', error);
      return {
        responsibilities: [],
        requirements: [],
        warning: this.buildNormalizationWarning(error),
      };
    }
  }

  private buildNormalizationWarning(error: unknown): JobWarning {
    const details = error instanceof Error ? error.message : null;
    return {
      status: 200,
      code: 'normalization_failed',
      message: NORMALIZATION_WARNING_MESSAGE,
      details,
    };
  }
}

const normalizeHostname = (hostname: string) =>
  hostname.split('%')[0].toLowerCase();

const isLocalHostname = (hostname: string) =>
  hostname === 'localhost' || hostname.endsWith('.local');

const isPrivateNetworkAddress = (hostname: string) => {
  const ipVersion = isIP(hostname);
  if (ipVersion === 4) {
    return isPrivateIpv4(hostname);
  }
  if (ipVersion === 6) {
    return isPrivateIpv6(hostname);
  }
  return false;
};

const isPrivateIpv4 = (ipAddress: string) => {
  if (ipAddress.startsWith('10.')) return true;
  if (ipAddress.startsWith('127.')) return true;
  if (ipAddress.startsWith('169.254.')) return true;
  if (ipAddress.startsWith('192.168.')) return true;
  if (ipAddress.startsWith('0.')) return true;

  const [first, second] = ipAddress.split('.').map(Number);
  if (first === 172 && second >= 16 && second <= 31) return true;

  return false;
};

const IPV6_LOOPBACKS = new Set(['::1', '0:0:0:0:0:0:0:1']);
const IPV6_LINK_LOCAL_PREFIXES = ['fe8', 'fe9', 'fea', 'feb'];

const isPrivateIpv6 = (ipAddress: string) => {
  const normalized = ipAddress.toLowerCase();
  if (IPV6_LOOPBACKS.has(normalized)) return true;
  if (normalized.startsWith('fc') || normalized.startsWith('fd')) return true;

  return IPV6_LINK_LOCAL_PREFIXES.some((prefix) =>
    normalized.startsWith(prefix),
  );
};

﻿import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ConfigService } from '@nestjs/config';
import { AllExceptionsFilter } from './common/filters/all-exceptions.filter';

async function bootstrap() {
  // Log anything that would otherwise kill a request or process silently
  process.on('unhandledRejection', (reason: any) => {
    console.error('unhandledRejection:', reason);
  });

  process.on('uncaughtException', (err: any) => {
    console.error('uncaughtException:', err);
  });

  const app = await NestFactory.create(AppModule);
  const config = app.get(ConfigService);

  app.useGlobalFilters(new AllExceptionsFilter());

  const corsOriginRaw =
    config.get<string>('CORS_ORIGIN') ?? 'http://localhost:3000';
  const envOrigins = corsOriginRaw
    .split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);
  const defaultOrigins = ['http://localhost:3000', 'http://127.0.0.1:3000'];
  const corsOrigins = Array.from(new Set([...defaultOrigins, ...envOrigins]));

  const corsOptions = {
    origin: (
      origin: string | undefined,
      callback: (err: Error | null, allow?: boolean) => void,
    ) => {
      if (!origin) {
        return callback(null, true);
      }

      if (corsOrigins.includes(origin)) {
        return callback(null, true);
      }

      return callback(new Error('Not allowed by CORS'), false);
    },
    credentials: true,
    methods: ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    optionsSuccessStatus: 204,
  };

  app.enableCors(corsOptions);

  const isProduction = config.get<string>('NODE_ENV') === 'production';
  if (!isProduction) {
    console.log(
      `DEV CORS allowlist: ${corsOrigins.join(', ')}; credentials enabled`,
    );
  }

  const port = config.get<number>('PORT') ?? 3001;

  await app.listen(port, '0.0.0.0');
}
bootstrap();

