import type { FitScoreVerdictLabel } from './fit-verdict';

const EXPERIENCE_SECTION_TYPES = ['EXPERIENCE', 'PROJECT', 'SUMMARY'];
const CX_PHRASES = [
  'customer experience',
  'cx operations',
  'customer support operations',
  'support operations',
];
const LEADERSHIP_MARKERS = [
  'manage',
  'managed',
  'lead',
  'led',
  'director',
  'senior manager',
  'global',
  'cross-functional',
  'stakeholder',
  'coaching',
];
const STRATEGIC_CUES = [
  'strategy',
  'strategic',
  'roadmap',
  'vision',
  'portfolio',
  'planning',
  'architecture',
];
const STRONG_INDUSTRY_MARKERS = ['security', 'saas', 'b2b', 'enterprise'];
const INCOMPATIBLE_INDUSTRY_MAP: Record<string, string[]> = {
  healthcare: ['finance', 'banking', 'regulated'],
  finance: ['healthcare', 'gaming', 'consumer'],
  government: ['gaming'],
  consumer: ['enterprise', 'b2b', 'saas'],
  gaming: ['regulated', 'government'],
};

const STOPWORDS = new Set([
  'a',
  'an',
  'and',
  'are',
  'as',
  'at',
  'be',
  'by',
  'for',
  'from',
  'has',
  'have',
  'in',
  'is',
  'it',
  'its',
  'of',
  'on',
  'or',
  'our',
  'that',
  'the',
  'their',
  'they',
  'this',
  'to',
  'we',
  'with',
  'will',
  'you',
  'your',
]);

const DEFAULT_WEIGHTS: Record<keyof FitScoreDimensionScores, number> = {
  experienceAlignment: 0.3,
  leadershipLevel: 0.25,
  strategicTacticalFit: 0.2,
  industryContext: 0.15,
  technicalPlatformFit: 0.1,
};

const combineSections = (
  sections: FitScoreInput['baseline']['sections'],
  types?: string[],
) =>
  sections
    .filter((section) => section.content)
    .filter((section) => {
      if (!types?.length) return true;
      const type = (section.type ?? '').toUpperCase();
      return Boolean(type && types.includes(type));
    })
    .map((section) => section.content)
    .join('\n');

const hashForCache = (text: string) =>
  createHash('sha256').update(text).digest('hex');

export class FitScoreInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'FitScoreInputError';
  }
}

type DimensionWithDetail = {
  score: number;
  detail: FitScoreDebugDimensionDetail;
};

type TechnicalDimensionResult = DimensionWithDetail & {
  missingRequiredTools: string[];
};

export class FitScoreEngine {
  private readonly embeddingProvider?: GapEmbeddingProvider;
  private readonly embeddingsEnabled: boolean;
  private readonly embeddingCache = new Map<string, number[]>();
  private readonly embeddingModel: string;

  constructor(embeddingProvider?: GapEmbeddingProvider) {
    this.embeddingProvider = embeddingProvider;
    this.embeddingsEnabled = Boolean(this.embeddingProvider?.isEnabled?.());
    this.embeddingModel =
      (this.embeddingProvider as unknown as { modelName?: string })
        ?.modelName ??
      (this.embeddingProvider as unknown as { model?: string })?.model ??
      'default';
  }

  async score(
    input: FitScoreInput,
    options?: FitScoreOptions,
  ): Promise<FitScoreResult> {
    const jobSelection = this.selectJobText(input.job);
    if (jobSelection.wordCount < 300) {
      throw new FitScoreInputError(
        'Job text must contain at least 300 words for reliable scoring.',
      );
    }

    const baselineText = combineSections(input.baseline.sections);
    const baselineWordCount = countWords(baselineText);
    const baselineExperienceText = combineSections(
      input.baseline.sections,
      EXPERIENCE_SECTION_TYPES,
    );

    const experience = await this.scoreExperienceAlignment(
      jobSelection.text,
      baselineExperienceText,
      baselineText,
    );
    const leadership = await this.scoreLeadershipLevel(
      jobSelection.text,
      baselineExperienceText,
    );
    const strategic = await this.scoreStrategicFit(
      jobSelection.text,
      baselineText,
    );
    const industry = await this.scoreIndustryContext(
      jobSelection.text,
      baselineText,
    );
    const technical = await this.scoreTechnicalPlatformFit(
      jobSelection.text,
      baselineText,
    );

    const dimensionScores: FitScoreDimensionScores = {
      experienceAlignment: experience.score,
      leadershipLevel: leadership.score,
      strategicTacticalFit: strategic.score,
      industryContext: industry.score,
      technicalPlatformFit: technical.score,
    };

    const appliedWeights = this.applyDimensionWeights(options?.weights);
    const weightSum =
      Object.values(appliedWeights).reduce(
        (total, value) => total + value,
        0,
      ) || 1;
    const baseRawScore = clamp(
      Math.round(
        (dimensionScores.experienceAlignment *
          appliedWeights.experienceAlignment +
          dimensionScores.leadershipLevel * appliedWeights.leadershipLevel +
          dimensionScores.strategicTacticalFit *
            appliedWeights.strategicTacticalFit +
          dimensionScores.industryContext * appliedWeights.industryContext +
          dimensionScores.technicalPlatformFit *
            appliedWeights.technicalPlatformFit) /
          weightSum,
      ),
    );
    const signalBoost = this.hasStrongSignal(dimensionScores) ? 20 : 0;
    const rawScore = clamp(baseRawScore + signalBoost);

    const missingRequiredToolsCount = technical.missingRequiredTools.length;
    const penalty = Math.min(10, missingRequiredToolsCount * 3);
    let finalScore = rawScore - penalty;
    let leadershipOverrideApplied = false;

    if (
      dimensionScores.leadershipLevel >= 80 &&
      dimensionScores.strategicTacticalFit >= 75
    ) {
      finalScore = Math.max(finalScore, 70);
      leadershipOverrideApplied = true;
    }

    finalScore = clamp(finalScore);

    const verdictLabel = verdictFromScore(finalScore);
    const strengths = buildStrengths(
      jobSelection.text,
      baselineText,
      dimensionScores,
    );
    const gaps = buildGaps(technical.missingRequiredTools, dimensionScores);
    const summary =
      'Weighted fit based on leadership, experience alignment, strategy, industry context, and tools. Tools are a modest factor; missing required tools apply a bounded penalty.';

    const debug: FitScoreDebugPayload | undefined = options?.debug
      ? {
          weights: appliedWeights,
          rawScore,
          signalBoost,
          finalScore,
          missingRequiredToolsCount,
          missingRequiredToolsPenalty: penalty,
          leadershipOverrideApplied,
          chosenTextSource: jobSelection.source,
          jobWordCount: jobSelection.wordCount,
          baselineWordCount,
          verdict: verdictLabel,
          dimensionDetails: {
            experienceAlignment: {
              score: dimensionScores.experienceAlignment,
              semanticScore: experience.detail.semanticScore,
              keywordBoost: experience.detail.keywordBoost,
            },
            leadershipLevel: {
              score: dimensionScores.leadershipLevel,
              semanticScore: leadership.detail.semanticScore,
              structuredScore: leadership.detail.structuredScore,
            },
            strategicTacticalFit: {
              score: dimensionScores.strategicTacticalFit,
              semanticScore: strategic.detail.semanticScore,
              keywordBoost: strategic.detail.keywordBoost,
            },
            industryContext: {
              score: dimensionScores.industryContext,
              semanticScore: industry.detail.semanticScore,
              keywordBoost: industry.detail.keywordBoost,
              fallbackScore: industry.detail.fallbackScore,
            },
            technicalPlatformFit: {
              score: dimensionScores.technicalPlatformFit,
              semanticScore: technical.detail.semanticScore,
              keywordBoost: technical.detail.keywordBoost,
              fallbackScore: technical.detail.fallbackScore,
            },
          },
        }
      : undefined;

    return {
      overallScore: finalScore,
      rawScore,
      verdict: verdictLabel,
      persistenceVerdict: this.mapPersistenceVerdict(verdictLabel),
      dimensionScores,
      strengths,
      gaps,
      summary,
      missingRequiredTools: technical.missingRequiredTools,
      missingRequiredToolsCount,
      missingRequiredToolsPenalty: penalty,
      leadershipOverrideApplied,
      complianceFlags: [],
      debug,
    };
  }

  private applyDimensionWeights(
    overrides?: DimensionWeightOverrides | null,
  ): Record<keyof FitScoreDimensionScores, number> {
    const weights: Record<keyof FitScoreDimensionScores, number> = {
      experienceAlignment: DEFAULT_WEIGHTS.experienceAlignment,
      leadershipLevel: DEFAULT_WEIGHTS.leadershipLevel,
      strategicTacticalFit: DEFAULT_WEIGHTS.strategicTacticalFit,
      industryContext: DEFAULT_WEIGHTS.industryContext,
      technicalPlatformFit: DEFAULT_WEIGHTS.technicalPlatformFit,
    };

    (Object.keys(weights) as Array<keyof FitScoreDimensionScores>).forEach(
      (dimension) => {
        weights[dimension] = weights[dimension] * (overrides?.[dimension] ?? 1);
      },
    );

    return weights;
  }

  private selectJobText(job: FitScoreInput['job']) {
    const override = job.jobTextOverride?.trim();
    if (override) {
      return {
        text: override,
        wordCount: countWords(override),
        source: 'rawDescription',
      };
    }
    const jobPrompt = buildJobPromptText(job);
    return {
      text: jobPrompt.text,
      wordCount: jobPrompt.wordCount,
      source: jobPrompt.source,
    };
  }

  private async scoreExperienceAlignment(
    jobText: string,
    baselineExperienceText: string,
    baselineText: string,
  ): Promise<DimensionWithDetail> {
    const semanticScore = this.referenceCoverage(
      jobText,
      baselineExperienceText,
    );
    const cxBoost = this.computeCxBoost(jobText, baselineText);
    const finalScore = clamp(semanticScore + cxBoost);

    return {
      score: finalScore,
      detail: {
        score: finalScore,
        semanticScore,
        keywordBoost: cxBoost,
      },
    };
  }

  private computeCxBoost(jobText: string, baselineText: string) {
    const normalizedJob = normalizeText(jobText);
    const normalizedBaseline = normalizeText(baselineText);
    const matches = CX_PHRASES.filter(
      (phrase) =>
        normalizedJob.includes(phrase) && normalizedBaseline.includes(phrase),
    ).length;
    return Math.min(10, matches * 4);
  }

  private async scoreLeadershipLevel(
    jobText: string,
    baselineLeadershipText: string,
  ): Promise<DimensionWithDetail> {
    const semanticScore = this.referenceCoverage(
      jobText,
      baselineLeadershipText,
    );

    const normalizedJob = normalizeText(jobText);
    const normalizedBaseline = normalizeText(baselineLeadershipText);
    const jobCount = LEADERSHIP_MARKERS.filter((marker) =>
      normalizedJob.includes(marker),
    ).length;
    const baselineCount = LEADERSHIP_MARKERS.filter((marker) =>
      normalizedBaseline.includes(marker),
    ).length;
    const structuredScore =
      jobCount === 0 ? 65 : clamp(Math.min(baselineCount / jobCount, 1) * 100);
    const finalScore = clamp(
      Math.round(semanticScore * 0.7 + structuredScore * 0.3),
    );

    return {
      score: finalScore,
      detail: {
        score: finalScore,
        semanticScore,
        structuredScore,
      },
    };
  }

  private async scoreStrategicFit(
    jobText: string,
    baselineText: string,
  ): Promise<DimensionWithDetail> {
    const semanticScore = this.referenceCoverage(jobText, baselineText);

    const normalizedJob = normalizeText(jobText);
    const normalizedBaseline = normalizeText(baselineText);
    const matchCount = STRATEGIC_CUES.filter(
      (cue) => normalizedJob.includes(cue) && normalizedBaseline.includes(cue),
    ).length;
    const keywordBoost = Math.min(10, matchCount * 3);
    const finalScore = clamp(semanticScore + keywordBoost);

    return {
      score: finalScore,
      detail: {
        score: finalScore,
        semanticScore,
        keywordBoost,
      },
    };
  }

  private async scoreIndustryContext(
    jobText: string,
    baselineText: string,
  ): Promise<DimensionWithDetail> {
    const normalizedJob = normalizeText(jobText);
    const normalizedBaseline = normalizeText(baselineText);

    let keywordScore = 50;
    let strongMatches = 0;
    let incompatiblePenalty = 0;

    STRONG_INDUSTRY_MARKERS.forEach((marker) => {
      if (normalizedJob.includes(marker)) {
        if (normalizedBaseline.includes(marker)) {
          keywordScore += 10;
          strongMatches += 1;
        }
        const conflicts = INCOMPATIBLE_INDUSTRY_MAP[marker] ?? [];
        if (
          conflicts.some((conflict) => normalizedBaseline.includes(conflict))
        ) {
          incompatiblePenalty = -10;
        }
      }
    });

    keywordScore = Math.min(keywordScore, 90);

    const semanticFallback = Math.round(
      (await this.computeSemanticSimilarity(jobText, baselineText)) * 100,
    );

    const blendedScore =
      strongMatches >= 2
        ? clamp(keywordScore + incompatiblePenalty)
        : clamp(
            Math.round(keywordScore * 0.6 + semanticFallback * 0.4) +
              incompatiblePenalty,
          );

    return {
      score: blendedScore,
      detail: {
        score: blendedScore,
        semanticScore: semanticFallback,
        keywordBoost: keywordScore,
        fallbackScore: semanticFallback,
      },
    };
  }

  private async scoreTechnicalPlatformFit(
    jobText: string,
    baselineText: string,
  ): Promise<TechnicalDimensionResult> {
    const coverage = evaluateToolCoverage(jobText, baselineText);
    const finalScore = clamp(
      Math.round(
        coverage.requiredCoverage * 70 + coverage.preferredCoverage * 30,
      ),
    );
    return {
      score: finalScore,
      missingRequiredTools: coverage.missingRequired,
      detail: {
        score: finalScore,
        semanticScore: Math.round(coverage.requiredCoverage * 100),
        keywordBoost: Math.round(coverage.preferredCoverage * 100),
        fallbackScore: coverage.missingRequired.length,
      },
    };
  }

  private mapPersistenceVerdict(
    label: FitScoreVerdictLabel,
  ): FitAssessmentVerdict {
    if (label === 'Apply') {
      return FitAssessmentVerdict.APPLY;
    }
    if (label === 'Consider') {
      return FitAssessmentVerdict.CONSIDER;
    }
    return FitAssessmentVerdict.SKIP;
  }

  private async computeSemanticSimilarity(
    textA: string,
    textB: string,
  ): Promise<number> {
    if (!textA || !textB) return 0;
    const [firstEmbedding, secondEmbedding] = await Promise.all([
      this.embedWithCache(textA),
      this.embedWithCache(textB),
    ]);
    if (firstEmbedding && secondEmbedding) {
      return this.cosineSimilarity(firstEmbedding, secondEmbedding);
    }
    return this.lexicalSimilarity(textA, textB);
  }

  private async embedWithCache(text: string): Promise<number[] | null> {
    if (!this.embeddingsEnabled || !this.embeddingProvider) {
      return null;
    }
    const key = `${this.embeddingModel}:${hashForCache(text)}`;
    if (this.embeddingCache.has(key)) {
      return this.embeddingCache.get(key) ?? null;
    }
    try {
      const embedding = await this.embeddingProvider.embed(text);
      this.embeddingCache.set(key, embedding);
      return embedding;
    } catch {
      return null;
    }
  }

  private cosineSimilarity(a: number[], b: number[]): number {
    if (!a.length || !b.length || a.length !== b.length) {
      return 0;
    }
    const dot = a.reduce((sum, value, index) => sum + value * b[index], 0);
    const magnitudeA = Math.sqrt(
      a.reduce((sum, value) => sum + value * value, 0),
    );
    const magnitudeB = Math.sqrt(
      b.reduce((sum, value) => sum + value * value, 0),
    );
    if (!magnitudeA || !magnitudeB) {
      return 0;
    }
    return dot / (magnitudeA * magnitudeB);
  }

  private lexicalSimilarity(textA: string, textB: string): number {
    const tokensA = new Set(tokenize(textA));
    const tokensB = new Set(tokenize(textB));
    if (!tokensA.size || !tokensB.size) {
      return 0;
    }
    const overlap = [...tokensA].filter((token) => tokensB.has(token)).length;
    const referenceSize = tokensB.size || tokensA.size;
    return overlap / Math.max(referenceSize, 1);
  }

  private normalizedTokens(text: string) {
    return tokenize(text).filter((token) => !STOPWORDS.has(token));
  }

  private referenceCoverage(jobText: string, baselineText: string): number {
    const normalizedJob = normalizeText(jobText);
    if (!normalizedJob) return 0;
    const baselineTokens = new Set(this.normalizedTokens(baselineText));
    if (!baselineTokens.size) return 0;
    let matches = 0;
    for (const token of baselineTokens) {
      if (normalizedJob.includes(token)) {
        matches += 1;
      }
    }
    return Math.round((matches / baselineTokens.size) * 100);
  }

  private hasStrongSignal(scores: FitScoreDimensionScores): boolean {
    return (
      scores.experienceAlignment >= 55 &&
      scores.leadershipLevel >= 50 &&
      scores.strategicTacticalFit >= 55
    );
  }
}

import { BadRequestException, NotFoundException } from '@nestjs/common';
import { StarStory } from './star-story.entity';
import { StarStoriesService } from './star-stories.service';

describe('StarStoriesService', () => {
  const mockStory: StarStory = {
    id: 'story-1',
    userId: 'user-1',
    title: 'Launch project',
    situation: 'System reliability was poor',
    task: 'Improve uptime',
    action: 'Led migration to HA setup',
    result: '99.9% uptime achieved',
    reflections: 'Need earlier monitoring',
    competencies: ['leadership'],
    createdAt: new Date('2024-01-01T00:00:00Z'),
    updatedAt: new Date('2024-01-01T00:00:00Z'),
  };

  const createMockRepository = () => ({
    create: jest.fn((data: Partial<StarStory>) => ({ ...mockStory, ...data })),
    save: jest.fn(async (data: StarStory) => data),
    find: jest.fn(),
    findOne: jest.fn(),
    remove: jest.fn(async (data: StarStory) => data),
  });

  const createService = (repository = createMockRepository()) =>
    new StarStoriesService(repository as never);

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('creates a STAR story with required fields', async () => {
    const repository = createMockRepository();
    const service = createService(repository);

    const result = await service.createStarStory('user-1', {
      title: ' Reliability fix ',
      situation: ' Outages ',
      task: ' Stabilize ',
      action: ' Added alerts ',
      result: ' Reduced incidents ',
      competencies: [' ops '],
      reflections: '  More runbooks  ',
    });

    expect(repository.create).toHaveBeenCalledWith(
      expect.objectContaining({
        userId: 'user-1',
        title: 'Reliability fix',
        situation: 'Outages',
        task: 'Stabilize',
        action: 'Added alerts',
        result: 'Reduced incidents',
        reflections: 'More runbooks',
        competencies: ['ops'],
      }),
    );
    expect(result.title).toBe('Reliability fix');
  });

  it('lists stories for a user', async () => {
    const repository = createMockRepository();
    repository.find.mockResolvedValue([mockStory]);
    const service = createService(repository);

    const stories = await service.listStarStoriesForUser('user-1');

    expect(repository.find).toHaveBeenCalledWith({
      where: { userId: 'user-1' },
      order: { createdAt: 'DESC' },
    });
    expect(stories).toEqual([mockStory]);
  });

  it('retrieves a story for a user', async () => {
    const repository = createMockRepository();
    repository.findOne.mockResolvedValue(mockStory);
    const service = createService(repository);

    const story = await service.getStarStoryForUser('story-1', 'user-1');

    expect(repository.findOne).toHaveBeenCalledWith({
      where: { id: 'story-1', userId: 'user-1' },
    });
    expect(story).toEqual(mockStory);
  });

  it('throws when story not found', async () => {
    const repository = createMockRepository();
    repository.findOne.mockResolvedValue(null);
    const service = createService(repository);

    await expect(
      service.getStarStoryForUser('missing', 'user-1'),
    ).rejects.toBeInstanceOf(NotFoundException);
  });

  it('updates a story with validation', async () => {
    const repository = createMockRepository();
    repository.findOne.mockResolvedValue({ ...mockStory });
    const service = createService(repository);

    const result = await service.updateStarStory('story-1', 'user-1', {
      title: ' Updated ',
      result: ' Better outcomes ',
      competencies: [' leadership ', ''],
      reflections: null,
    });

    expect(repository.save).toHaveBeenCalled();
    expect(result.title).toBe('Updated');
    expect(result.result).toBe('Better outcomes');
    expect(result.competencies).toEqual(['leadership']);
    expect(result.reflections).toBeNull();
  });

  it('throws when updating with empty required field', async () => {
    const repository = createMockRepository();
    repository.findOne.mockResolvedValue({ ...mockStory });
    const service = createService(repository);

    await expect(
      service.updateStarStory('story-1', 'user-1', { title: '' }),
    ).rejects.toBeInstanceOf(BadRequestException);
  });

  it('deletes a story', async () => {
    const repository = createMockRepository();
    repository.findOne.mockResolvedValue(mockStory);
    const service = createService(repository);

    const result = await service.deleteStarStory('story-1', 'user-1');

    expect(repository.remove).toHaveBeenCalledWith(mockStory);
    expect(result).toEqual({ deleted: true, id: 'story-1' });
  });
});

import {
  BadRequestException,
  Body,
  Controller,
  ForbiddenException,
  Get,
  Patch,
  Req,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import type { Request } from 'express';
import { UpdateSubscriptionTierDto } from './dto/update-subscription-tier.dto';
import { UsersService } from './users.service';
import { SubscriptionTier } from '../subscription/subscription-tier.enum';
import { UserRole } from './user.entity';
import { Entitlements } from '../features/feature-gates';

type UserRequest = Request & {
  user?: {
    id?: string;
    email?: string;
    role?: UserRole;
    subscriptionTier?: SubscriptionTier;
    entitlements?: Entitlements;
  };
};

@Controller('users')
@UseGuards(AuthGuard('jwt'))
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Get('me')
  me(@Req() request: UserRequest) {
    const user = request.user;

    if (!user) {
      throw new BadRequestException('Invalid user context');
    }

    return user;
  }

  @Patch('me/subscription-tier')
  async updateSubscriptionTier(
    @Body() body: UpdateSubscriptionTierDto,
    @Req() request: UserRequest,
  ) {
    const user = request.user;

    if (!user?.id) {
      throw new BadRequestException('Invalid user context');
    }

    const isProd = process.env.NODE_ENV === 'production';
    const isAdmin = user.role === 'admin';

    if (isProd && !isAdmin) {
      throw new ForbiddenException(
        'Subscription tier updates are disabled in production.',
      );
    }

    const requested = (body.tier ?? '').trim().toUpperCase();

    if (
      !Object.values(SubscriptionTier).includes(requested as SubscriptionTier)
    ) {
      throw new BadRequestException('Invalid subscription tier');
    }

    const updated = await this.usersService.updateSubscriptionTier(
      user.id,
      requested as SubscriptionTier,
    );

    const { passwordHash, ...sanitized } = updated;
    return sanitized;
  }
}

import { INestApplication } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import request from 'supertest';
import { DataSource, Repository } from 'typeorm';
import { AppModule } from '../../src/app.module';
import { AuthService } from '../../src/auth/auth.service';
import {
  ComplianceFlagCode,
  ComplianceFlagSeverity,
} from '../../src/compliance/compliance.types';
import {
  ComplianceService,
  ValidateAndAuditRequest,
  ValidateAndAuditResult,
} from '../../src/compliance/compliance.service';
import { Baseline } from '../../src/baseline/baseline.entity';
import {
  BaselineIncludePolicy,
  BaselineSectionType,
} from '../../src/baseline/baseline-section.entity';
import { BaselineVersion } from '../../src/baseline/baseline-version.entity';
import {
  FitAssessment,
  FitAssessmentVerdict,
} from '../../src/analysis/fit-assessment.entity';
import { Job, JobIngestionMethod } from '../../src/jobs/job.entity';

const INVENTED_CLAIM =
  'Improved revenue by 42% at InventedCorp as Senior Imaginary Strategist';
const SAFE_SECTION =
  'Documented responsible teamwork across product and platform environments.';
const SAFE_RESPONSIBILITY =
  'Synthesized stakeholder priorities into consistent delivery updates.';
const SAFE_REQUIREMENT =
  'Strong background in cross-platform automation and observability.';

describe('Compliance blocking for generation endpoints (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let baselineRepository: Repository<Baseline>;
  let baselineVersionRepository: Repository<BaselineVersion>;
  let jobRepository: Repository<Job>;
  let fitAssessmentRepository: Repository<FitAssessment>;
  let complianceService: ComplianceService;
  let mockValidateAndAudit: jest.SpyInstance<
    Promise<ValidateAndAuditResult>,
    [ValidateAndAuditRequest]
  >;
  let authToken: string;
  let userId: string;

  beforeAll(async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleRef.createNestApplication();
    await app.init();

    dataSource = app.get(DataSource);
    baselineRepository = dataSource.getRepository(Baseline);
    baselineVersionRepository = dataSource.getRepository(BaselineVersion);
    jobRepository = dataSource.getRepository(Job);
    fitAssessmentRepository = dataSource.getRepository(FitAssessment);

    const authService = moduleRef.get(AuthService);
    const registration = await authService.register({
      email: `compliance-test+${Date.now()}@example.com`,
      password: 'Test1234!',
    });
    authToken = registration.accessToken;
    userId = registration.user.id;

    complianceService = moduleRef.get(ComplianceService);
    mockValidateAndAudit = jest
      .spyOn(complianceService, 'validateAndAudit')
      .mockImplementation(async (payload: ValidateAndAuditRequest) => {
        const normalizedSections = (payload.generatedSections ?? [])
          .map((section) => String(section.content ?? ''))
          .join(' ');

        const hasInvented =
          normalizedSections.includes(INVENTED_CLAIM) ||
          (
            (payload.job as Partial<Job>)?.normalizedResponsibilities ?? []
          ).some((entry) => (entry ?? '').includes(INVENTED_CLAIM)) ||
          ((payload.job as Partial<Job>)?.normalizedRequirements ?? []).some(
            (entry) => (entry ?? '').includes(INVENTED_CLAIM),
          );

        const auditId = `audit-${payload.action}-${Date.now()}-${Math.random()
          .toString(16)
          .slice(2, 8)}`;

        const audit = {
          id: auditId,
          action: payload.action,
          actorId: payload.actorId,
          outputHash: payload.outputHash,
          baselineVersionId:
            ((payload.baselineVersion ?? {}) as Partial<BaselineVersion>).id ??
            null,
          baselineVersionHash:
            ((payload.baselineVersion ?? {}) as Partial<BaselineVersion>)
              .hash ??
            ((payload.baselineVersion ?? {}) as Partial<BaselineVersion>)
              .fileHash ??
            null,
          jobId: payload.job?.id ?? null,
          createdAt: new Date().toISOString(),
        };

        const inventedFlags = [
          {
            code: ComplianceFlagCode.INVENTED_METRIC,
            severity: ComplianceFlagSeverity.BLOCK,
            message: 'Detected invented metric',
          },
          {
            code: ComplianceFlagCode.INVENTED_COMPANY,
            severity: ComplianceFlagSeverity.BLOCK,
            message: 'Detected invented company reference',
          },
          {
            code: ComplianceFlagCode.INVENTED_ROLE,
            severity: ComplianceFlagSeverity.BLOCK,
            message: 'Detected invented role',
          },
        ];

        return {
          blocked: hasInvented,
          complianceFlags: hasInvented ? inventedFlags : [],
          audit,
        };
      });
  });

  afterEach(() => {
    mockValidateAndAudit.mockClear();
  });

  afterAll(async () => {
    await app.close();
  });

  async function createBaselineWithSections(
    sections: string[],
    versionNumber = 1,
  ) {
    const hash = `baseline-hash-${Date.now()}-${Math.random()
      .toString(16)
      .slice(2, 8)}`;

    const baseline = baselineRepository.create({
      userId,
      version: versionNumber,
      originalFilename: 'mock-baseline.docx',
      mimeType:
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      storagePath: `/tmp/baseline-${hash}.docx`,
      hash,
      sections: sections.map((content, index) => ({
        sectionType: BaselineSectionType.EXPERIENCE,
        title: null,
        content,
        includePolicy: BaselineIncludePolicy.ALWAYS,
        order: index,
      })),
    });

    const savedBaseline = await baselineRepository.save(baseline);
    const version = baselineVersionRepository.create({
      baselineId: savedBaseline.id,
      baseline: savedBaseline,
      versionNumber,
      fileHash: hash,
      storagePath: `/tmp/version-${hash}.bin`,
    });

    const savedVersion = await baselineVersionRepository.save(version);
    return { baseline: savedBaseline, baselineVersion: savedVersion };
  }

  async function createJobWithResponsibilities(responsibilities: string[]) {
    const job = jobRepository.create({
      userId,
      title: 'Platform Engineer',
      company: 'Acme Data Works',
      rawDescription: 'Maintain scalable infrastructure.',
      sourceUrl: 'https://example.com/job',
      normalizedResponsibilities: responsibilities,
      normalizedRequirements: [SAFE_REQUIREMENT],
      jdIngestionMethod: JobIngestionMethod.PASTE,
      jdParsedAt: new Date(),
    });

    return jobRepository.save(job);
  }

  async function createFitAssessmentFixture(
    job: Job,
    baseline: Baseline,
    baselineVersion: BaselineVersion,
  ) {
    const assessment = fitAssessmentRepository.create({
      userId,
      jobId: job.id,
      baselineId: baseline.id,
      baselineVersion: baselineVersion.versionNumber ?? 1,
      overallScore: 95,
      verdict: FitAssessmentVerdict.APPLY,
      dimensionScores: {
        experienceAlignment: 95,
        leadershipLevel: 90,
        technicalPlatformFit: 96,
        industryContext: 92,
        strategicTacticalFit: 91,
      },
      strengths: [],
      gaps: [],
      complianceFlags: [],
      inputsHash: 'fit-assessment-hash',
    });

    return fitAssessmentRepository.save(assessment);
  }

  async function buildFixture(options: {
    includeInventedClaimInSections?: boolean;
    includeInventedClaimInResponsibilities?: boolean;
  }) {
    const sections = [
      SAFE_SECTION,
      ...(options.includeInventedClaimInSections ? [INVENTED_CLAIM] : []),
    ];
    const { baseline, baselineVersion } = await createBaselineWithSections(
      sections,
      1,
    );

    const responsibilities = options.includeInventedClaimInResponsibilities
      ? [INVENTED_CLAIM]
      : [SAFE_RESPONSIBILITY];

    const job = await createJobWithResponsibilities(responsibilities);
    await createFitAssessmentFixture(job, baseline, baselineVersion);

    return { baseline, baselineVersion, job };
  }

  function authHeader() {
    return { Authorization: `Bearer ${authToken}` };
  }

  describe('blocking behavior', () => {
    it('blocks resume generation with invented claim', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: true,
      });

      const response = await request(app.getHttpServer())
        .post('/resume/generate')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
        });

      expect(response.status).toBe(422);
      const details = response.body.error?.details;
      expect(details?.audit_id).toBeTruthy();
      expect(details?.compliance_flags).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ code: ComplianceFlagCode.INVENTED_METRIC }),
          expect.objectContaining({
            code: ComplianceFlagCode.INVENTED_COMPANY,
          }),
          expect.objectContaining({ code: ComplianceFlagCode.INVENTED_ROLE }),
        ]),
      );
    });

    it('blocks resume export when the same invented claim is present', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: true,
      });

      const response = await request(app.getHttpServer())
        .post('/resume/export')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
          format: 'docx',
        });

      expect(response.status).toBe(422);
      const details = response.body.error?.details;
      expect(details?.audit_id).toBeTruthy();
      expect(details?.compliance_flags).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ code: ComplianceFlagCode.INVENTED_METRIC }),
        ]),
      );
    });

    it('blocks cover letter generation when responsibilities cite the invented claim', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
        includeInventedClaimInResponsibilities: true,
      });

      const response = await request(app.getHttpServer())
        .post('/cover-letters/generate')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
        });

      expect(response.status).toBe(422);
      const details = response.body.error?.details;
      expect(details?.audit_id).toBeTruthy();
      expect(details?.compliance_flags).toEqual(
        expect.arrayContaining([
          expect.objectContaining({
            code: ComplianceFlagCode.INVENTED_COMPANY,
          }),
        ]),
      );
    });

    it('blocks follow-up generation when notes include the invented claim', async () => {
      const { baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
      });

      const response = await request(app.getHttpServer())
        .post(`/interview-toolkit/${job.id}/follow-up`)
        .set(authHeader())
        .send({
          baselineVersionId: baselineVersion.id,
          notes: INVENTED_CLAIM,
        });

      expect(response.status).toBe(422);
      const details = response.body.error?.details;
      expect(details?.audit_id).toBeTruthy();
      expect(details?.compliance_flags).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ code: ComplianceFlagCode.INVENTED_ROLE }),
        ]),
      );
    });
  });

  describe('happy paths', () => {
    it('allows resume generation when content is grounded', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
      });

      const response = await request(app.getHttpServer())
        .post('/resume/generate')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
        });

      expect(response.status).toBe(201);
      expect(response.body.ok).toBe(true);
      expect(response.body.compliance_flags).toEqual([]);
      expect(response.body.audit_id).toBeTruthy();
    });

    it('exports a resume successfully when content is safe', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
      });

      const response = await request(app.getHttpServer())
        .post('/resume/export')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
          format: 'docx',
        });

      expect(response.status).toBe(200);
      expect(response.headers['content-disposition']).toMatch(/resume\.docx/);
      expect(response.headers['content-type']).toMatch(
        /application\/vnd\.openxmlformats-officedocument\.wordprocessingml\.document/,
      );
    });

    it('creates a cover letter when no invented claim is introduced', async () => {
      const { baseline, baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
      });

      const response = await request(app.getHttpServer())
        .post('/cover-letters/generate')
        .set(authHeader())
        .send({
          baselineId: baseline.id,
          baselineVersionId: baselineVersion.id,
          jobId: job.id,
        });

      expect(response.status).toBe(201);
      expect(response.body.compliance_flags).toEqual([]);
      expect(response.body.audit_id).toBeTruthy();
    });

    it('generates follow-up copy when notes are safe', async () => {
      const { baselineVersion, job } = await buildFixture({
        includeInventedClaimInSections: false,
      });

      const response = await request(app.getHttpServer())
        .post(`/interview-toolkit/${job.id}/follow-up`)
        .set(authHeader())
        .send({
          baselineVersionId: baselineVersion.id,
          notes: 'Thanks again for the chance to speak about the role.',
        });

      expect(response.status).toBe(201);
      expect(response.body.complianceFlags).toEqual([]);
      expect(response.body.auditId).toBeTruthy();
    });
  });
});
